quests[25886] = { id = 25886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Vorteil nutzen", description = "Wie es scheint, hat ein Großteil des Schattenhammers sich zurückfallen lassen, um sich für einen weiteren Angriff neu zu formieren. Nur ihre besten Kämpfer halten noch die Front. Dies ist unsere Gelegenheit, um ihren Anführern den Garaus zu machen.\n\nSchwärmt aus über die Verbrannte Ebene und vernichtet die Zwielichtfeldhauptmänner. Wir werden sie von dieser Welt tilgen!", sourceObjective = "Tötet 4 Zwielichtfeldhauptmänner.", completion = "Ausgezeichnet! Der Schattenhammer wird zweifellos versuchen, den Berg zurückzuerobern, aber dafür müssen sie jetzt auf die Führerschaft dieser hirnlosen Muskelpakete verzichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25887] = { id = 25887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welle der Zerstörung", description = "Unsere Zeit hier neigt sich dem Ende zu. Ich muss diesen Nagaflüchtlingen irgendwie folgen, wenn wir herausfinden wollen, was sie in dieser Gegend vorhaben.\n\nAber bevor ich weiterziehe will ich sehen, wie dieser Ort hier vernichtet wird!\n\nEgal, wie viele es sind, ich habe einen Plan, der für Chancengleichheit sorgen wird.\n\nAußerhalb der Höhle suchen ausgemergelte große Haie, die von den Naga vertrieben wurden, nach Nahrung.\n\nIn ihrem geschwächten Zustand sind sie für Anregungen sehr empfänglich. Benutzt diese Kugel, um sie zu unterwerfen und hetzt sie dann direkt auf unseren Feind.", sourceObjective = "Benutzt die Kugel der Anregung, um einen ausgemergelten großen Hai zu unterwerfen und benutzt ihn dann, um 12 Gefolgsleute des Zin'jatar in der Umklammerung zu töten.", completion = "Genau so soll es sein.\n\nJetzt ist der Weg frei, um diesen Naga einen letzten vernichtenden Schlag zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25888] = { id = 25888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Soldat inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Soldaten in der Umklammerung.", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25889] = { id = 25889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kinder!", description = "Meine armen, hilflosen Schüler sitzen im Hain von Thal'darah fest. Wegen der Schlacht, die im Kriegsnarbental tobt, können sie nicht entkommen. Wir müssen die Kinder retten, bevor die Horde ihre Bombe abwirft!\n\nNehmt meinen Hippogryphen und rettet damit die jungen Druiden im Hain von Thal'darah. Setzt sie am Hippogryphenposten hier in der Stadt ab.\n\nRettet sie alle, {name}! Ihr seid wahrlich unsere einzige Hoffnung.", sourceObjective = "Rettet mit Meister Thal'darahs Hippogryphen 5 hilflose junge Druiden aus dem Hain von Thal'darah.", progress = "Ruft meinen Hippogryphen mit der Pfeife, {name}.", completion = "Habt Dank, {name}. Der Held, auf den wir gewartet haben, ist endlich gekommen - und keinen Augenblick zu früh.", sourceObjectiveStatus = "unverified-source-field" }
quests[25890] = { id = 25890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nespirah", description = "Jetzt ist mir klar, was wir tun müssen, {name}.\n\nDie Naga können diese Perlen nur von einem Ort haben: Nespirah, das uralte Schalenwesen, das außerhalb dieser Höhle ruht. Warum Nespirah sich den Naga unterwirft, ist mir allerdings schleierhaft.\n\nWir können durch eine kleine Röhre in der Nähe des Ausgangs dieser Höhle in Nespirahs Körper eindringen. Ich muss zuerst noch meinen Meister holen, danach können wir uns im Inneren treffen. Wir werden Nespirah durch den nordwestlichen Eingang betreten.", sourceObjective = "Betretet Nespirahs nordwestlichen Eingang und findet dann einen Weg, um mit ihr zu sprechen.", completion = "Erunak vertraut diese Aufgabe mir an? Nun gut. Mal sehen, was wir von der Ahnin lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25891] = { id = 25891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Letzte Anstrengung", description = "Die Horde signalisiert den Rückzug. Seht, wie sie das Schlachtfeld verlassen - das ist der Vorbote einer Katastrophe.\n\nWir müssen ein letztes Mal im Hain von Thal'darah landen. Ich würde es nicht ertragen, wenn auch nur ein junger Druide zurückbleiben müsste.\n\nHelft mir, <Held/Heldin>. Ich nehme die Zügel. Sucht Ihr nach Druiden, die vielleicht zurückgelassen wurden.\n\nWir brechen auf, wenn Ihr bereit seid.", sourceObjective = "Helft Meister Thal'darah bei der Suche nach Druiden, die im Hain von Thal'darah zurückgelassen wurden.", completion = "Wisst Ihr, weshalb die Horde zerstört? Die Horde zerstört, weil sie Schönheit nicht begreifen kann. Sie fürchtet sie, und was sie fürchtet, muss sie zerstören. Warum sonst zerstört sie den Hain von Thal'darah?\n\nGemeinsam werden wir dafür sorgen, dass sie etwas verstehen. Sie werden verstehen, dass ihre Taten einen hohen Preis fordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25892] = { id = 25892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt Wellensprecherin Valorens Seepferd, um zu Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Freut mich sehr, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25893] = { id = 25893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Jorlan und Hexasept sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Ingenieur Hexasept auf dem Biel'arangrat.", completion = "Pünktlich wie ein Uhrwerk! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Uhrwerk!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25894] = { id = 25894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Hexasept kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Kiemengoblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Kiemengoblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25895] = { id = 25895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Wir müssen immer vorbereitet sein. Wir müssen Ausrüstung haben. Wir müssen Pläne haben!\n\nAlle Schiffe in der Flotte der Allianz sind mit einer Überlebensausrüstung ausgestattet. Viele unserer Werkzeuge stammen aus so einer Überlebensausrüstung. Mein Ballon war auch in so einer Überlebensausrüstung enthalten! Aber jetzt ist sie aufgebraucht. Ich brauche noch eine Überlebensausrüstung!\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren und die Überlebensausrüstung nicht mitgenommen haben. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Allianz.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25896] = { id = 25896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andächtige Versammlung", description = "Ah, Kriegsmaid. Das Wort und der Wille unserer Lady sind mit Euch. Ich möchte Euch um einen Gefallen bitten…\n\nTiefenrufer Azrajar und meine Gezeitenpriesterinnen müssen zurückkehren, damit wir mit dem Ritual beginnen können. Könnt Ihr ihnen meinen Wunsch überbringen? Ihr solltet sie auf der Tempelterrasse und den Treppen unten finden. Azrajar hält sich an der Treppe im Norden auf.", sourceObjective = "Sucht Tiefenrufer Azrajar in der Mitte der nördlichen Treppe sowie 6 Gezeitenpriesterinnen der Sira'kess auf der oberen Ebene der Ruinen und tragt ihnen auf, zum Tempel zurückzukehren.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Die Kvaldir haben sich als größere Bedrohung herausgestellt, als wir dachten. Aber unsere Pläne konnten sie nicht im Geringsten vereiteln. Wenn unsere Verbündeten eintreffen, werden wir mehr als genug Streitkräfte haben, um den Gezeitenjäger zu stürzen.\n\nWir müssen nur sicherstellen, dass das Beschwörungsritual abgeschlossen werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25897] = { id = 25897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Überhaupt keinen!\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Unbedingt!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25898] = { id = 25898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Welch günstiger Zufall.\n\nJorlan ist bereits nach oben geschwommen, um ihn zu packen. Ist hochgeschwommen und wartet jetzt dort. Er meinte aber, er würde Euch die Ehre überlassen. So ist Jorlan eben.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Allianz Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Allianzschiffe.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25899] = { id = 25899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Die flammende Armee, die oben auf dem Hügel so viel Verwüstung angerichtet hat, hat sich in den Osten zurückgezogen. Nur die sengenden Fürsten sind noch zugange. Wenn wir ihre Reihen durchbrechen könnten, um uns mit Hauptmann Eisenstamms Truppen zusammenzutun, könnte ihre gesamte Offensive scheitern.\n\n{class}, ich bin nicht in der körperlichen Verfassung, noch weiter zu kämpfen, aber Ihr seht aus, als könntet Ihr ihnen noch die ein oder andere Blessur zufügen. Tötet diese sengenden Fürsten und formiert Euch mit Hauptmann Eisenstamm neu!", sourceObjective = "Tötet 10 sengende Zwielichtfürsten.", completion = "Wie viele habt Ihr getötet? Sieh mal an. Ein beeindruckendes Schauspiel. Ich schätze, meine Männer haben jetzt keine Ausreden mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25900] = { id = 25900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ich kann mir kaum vorstellen, dass Nespirah freiwillig zulässt, dass diese Naga in ihrer Schale ihr Lager aufschlagen. So wie ich das sehe, ist eines von zwei Dingen geschehen: Entweder haben sie sie überzeugt, sich ihrer Sache anzuschließen, oder sie haben sie so geschwächt, dass sie sich nicht wehren kann. Beide Möglichkeiten sind nicht gut.\n\nHier in diesem Raum sollte ich direkt mit Nespirah kommunizieren können. Finden wir es also selbst heraus. Sprecht mit mir, wenn Ihr bereit seid, {class}.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Das ist nicht so gut gelaufen. Aus irgendeinem Grund antwortet das Geschöpf mir nicht.\n\n<Duarn ist sichtlich frustriert.>\n\nWenn Erunak uns nur nicht verlassen hätte! Er wüsste sicher, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25901] = { id = 25901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung auf dem Hyjal", description = "Verstärkung! Ich dachte, wir müssen hier bis zum bitteren Ende kämpfen.\n\nEs sind nur noch wenige Wächter des Hyjal übrig. Zudem gehen uns langsam aber sicher die Vorräte aus. Auf dem Schlachtfeld um unsere letzte Bastion herum sollte eine Unmenge noch funktionstüchtiger Pfeile herumliegen.\n\nIch weiß, dass es für jemanden mit Euren Fähigkeiten fast schon lächerlich einfach ist, aber könntet Ihr unsere gebrauchte Munition aufsammeln? Nur so können wir unsere Vorräte aufstocken.", sourceObjective = "Sammelt 15 Pfeile des Aufsehers.", progress = "Pfeile des Aufsehers werden aus lebender Eiche geschnitzt und in den Mondbrunnen gesegnet. Ihre Pfeilspitzen bestehen aus Obsidian, das mit Runen verziert ist, die den Segen der Natur beschwören.\n\nSie sind nicht gerade billig.", completion = "Wunderbar! Immer noch scharf. Die Befiederung ist ein wenig blutig, aber sie fliegen noch gerade.\n\nDanke, {name}. Jetzt können wir den Hyjal weiter verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25902] = { id = 25902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erstes Totem!" }
quests[25903] = { id = 25903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist heiß und möglicherweise explosiv", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[25904] = { id = 25904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer und der Schlüssel", description = "Meine Nemesis. Ist noch am Leben.\nDie Diener des Feuers noch auf dem Vormarsch.\nWir müssen ihnen folgen. In ihren Bau.\n\nDie Oger kennen den Weg.\nTötet die Feldhauptmänner.\n\nBergt die Glyphe des Öffnens.\n\nSo soll es sein.", sourceObjective = "Tötet einen Zwielichtfeldhauptmann und besorgt Euch die Glyphe des Öffnens.", progress = "Die Glyphe. Zeigt sie mir.", completion = "Diese Macht ist uralt.\nPrimitiv.\nEinfach.\n\nWir werden sie gegen sie einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25905] = { id = 25905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widder auf der Flucht", description = "Die Widder, die wir hier auf dem Gehöft Bernruh züchten und ausbilden, werden von den Gebirgsjägern von Dun Morogh als Reittiere verwendet. Ja, es sind ein paar hier, aber nicht genug, um meine Familie und all die Tiere zu schützen.\n\nEinige mutige Frostmähnenräuber stehlen in letzter Zeit unsere Widder im Schutz der Nacht und bringen sie nach Süden in die Tundridhügel. Würdet Ihr uns helfen, sie zurückzuholen? Geht nah an sie heran und stoßt einen schrillen Pfiff aus, um ihre Aufmerksamkeit zu erregen. Den Rest erledigt ihre Ausbildung.", sourceObjective = "Benutzt /pfeifen, um 6 gestohlene Widder aus den Tundridhügeln zurückzuholen.", completion = "Die Widder, die Ihr gerettet habt, sind in ihren Stall zurückgekehrt. Meine Familienmitglieder werden sie ab jetzt Tag und Nacht bewachen. Diese Trolle werden uns nicht noch einmal übertölpeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[25906] = { id = 25906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dritte Flammentor", description = "Prägt Euch die Glyphe ein.\nNehmt sie mit Euch.\nZeichnet sie auf den Boden vor dem Flammentor.\nÖstlich von hier.\nBetretet die Feuerlande.\n\nIch kann nicht mit Euch kommen.\nAber meine Kinder erwarten Euch.\n\nSucht Garunda Bergkuppe im Reich der Flammen.", sourceObjective = "Reist durch das Flammentor in der Verbrannten Ebene und sucht nach Garunda Bergkuppe.", completion = "Der Schildkrötengott hat Euch geschickt? Gepriesen sei sein heiliger Panzer! Ich dachte, ich wäre hier unten für immer gefangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25907] = { id = 25907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklavenarbeit", description = "Ich werde ein wenig Zeit benötigen, um diese Barriere zu durchbrechen und mit Nespirah zu kommunizieren. In der Zwischenzeit könnt Ihr einige der Männer retten, die die Naga in den Gruben unter uns versklavt haben.\n\n<Duarn holt ein langes Seil aus seinen Roben hervor.>\n\nDas wird Euch sicher gute Dienste leisten.", sourceObjective = "Benutzt Duarns Seil, um 8 versklavte Perlenminenarbeiter zu retten.", completion = "Ausgezeichnete Arbeit, {name}… Obwohl ich fürchte, dass ich nicht annähernd so produktiv war wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25908] = { id = 25908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestraft sie", description = "Ich kann vielleicht nicht direkt mit Nespirah kommunizieren, aber ich kann zumindest indirekt etwas spüren. Zum Beispiel fühle ich deutlich, dass Nespirah alles andere als glücklich über die Anwesenheit der Naga hier ist.\n\nAls wir in Nespirahs Körper eingedrungen sind, sah ich Dutzende von Schildwachen und Verzauberinnen, die im zentralen Raum patrouillieren. Vielleicht könnt Ihr das Leid der Ahnin lindern, indem Ihr ihre Zahlen verringert.", sourceObjective = "Tötet 7 Schildwachen des Idra'kess und 7 Verzauberinnen des Idra'kess.", completion = "Könnt Ihr es fühlen? Wenn Ihr nur einen Tropfen Schamanenblut in Euch tragt, müsst Ihr das Gefühl der Erleichterung in der Luft spüren.\n\nNespirah ist erfreut. Vielleicht spricht sie jetzt endlich mit uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[25909] = { id = 25909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25910] = { id = 25910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit für Gnade ist vorbei", description = "Diese Höhle ist der reinste Höllenschlund, {name}. Sie ist voller abscheulicher Schrecken aus der Tiefe.\n\nIch möchte nicht, dass diese… Kreaturen… durch das Portal in die Außenwelt gelangen. Tötet sie alle!", sourceObjective = "Tötet 10 geschmolzene Peiniger und 4 Meister der Schattenflamme.", completion = "Also ist es vollbracht.\n\nDas Wissen, dass der Schattenhammerkult gemeinsame Sache mit solch abstoßenden und bösartigen Wesen macht… bringt mein Blut zum Kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25911] = { id = 25911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Kapitän Taylor am Stillen Strand zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ich weiß nicht, wie ich Euch für all das belohnen kann, das Ihr in diesem Meer getan habt, aber ich werde mir etwas einfallen lassen.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25912] = { id = 25912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute alte Zeit", description = "Die Welt gerät aus den Fugen, {name}. Vertraute Feinde versuchen uns an einer Seite zu zerstören, während uralte Kräfte uns von der anderen bedrängen.\n\n<Urahnin Sareth'na seufzt.>\n\nIch habe bessere Zeiten erlebt - hellere Tage, und ich sehne mich nach ihnen...\n\nHinter dem Steinkrallengipfel stehen die Ruinen unseres alten Außenpostens - die Dunkelheit hat ihn überrannt. Solltet Ihr Euch in dieser Gegend aufhalten, könntet Ihr dann nach meinem Zeichenbuch suchen? Es steckt voller glücklicher Erinnerungen. Ich würde Euch gut für seine Rückgabe belohnen.", sourceObjective = "Findet das Zeichenbuch der Urahnin Sareth'na.", progress = "Habt Ihr mein Zeichenbuch gefunden?", completion = "Ihr habt es gefunden! Möge Elune Euch segnen, Kind! Vielleicht verleiht mir dieses Buch die Kraft weiterzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25913] = { id = 25913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe", description = "Als die Horde ins Steinkrallengebirge einmarschierte, fiel mir auf, dass einige der Schildwachen krank wurden. Kurz darauf verhielten sie sich seltsam. Als der erste Tentakel aus dem Boden schoss, griffen die kranken Schildwachen uns an. Wir verloren den Außenposten kurz danach...\n\nDie Schildwachen im Gipfel sind nur noch Hüllen. In ihnen steckt etwas Böses. Bettet die Schildwachen zur letzten Ruhe und bringt ihre Gleven an Euch. Mit jeder zurückgebrachten Gleve kann eine gefallene Schwester identifiziert werden.", sourceObjective = "Bergt 8 Schildwachengleven.", progress = "Bergt die Schildwachengleven, {name}. Jede Gleve lässt sich einer Schildwache zuordnen.", completion = "Danke, {name}. Auf jede der Gleven ist der Name ihrer Besitzerin eingestanzt. Jetzt können wir ihre Familien benachrichtigen und ihren Seelen Frieden geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25914] = { id = 25914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Tiefe!", description = "Ranken schießen aus dem Boden und terrorisieren den Steinkrallengipfel. Meine Schildwachen werden ihrer nicht Herr.\n\nIch vermute, dass es im Herzen des Steinkrallengipfels eine Macht gibt, die diese Ranken kontrolliert. Wenn wir diese Macht aufhalten, werden die Ranken vielleicht in die Tiefen zurückkehren, aus denen sie gekommen sind.", sourceObjective = "Tötet Aph'lass und 10 einfallende Tentakel.", completion = "Der Tod des Boten Aph'lass hat leider nicht zu einem Ende der Rankenangriffe geführt. Ihr habt getan, was Ihr konntet, {name}. Dafür danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25915] = { id = 25915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Stärke", description = "Der dunkle Usurpator Nemesis floh hierher, als die Feuer des Hyjal verglommen. Wir sind noch nicht stark genug, um Nemesis zu besiegen, {name}, aber wir können vielleicht seine eigene Stärke gegen ihn verwenden.\n\nIch werde einen Abkömmling Tortollas mit Euch entsenden, eines der Kinder, das Ihr aus der Verderbnis des Zwielichts errettet habt.\n\nSucht in den Tiefen dieser Höhle nach einem Nemesiskristall und erlaubt der jungen Schildkröte, ihn zu untersuchen.\n\nFalls Ihr Euren Begleiter verliert, meldet Euch bei mir!", sourceObjective = "Begleitet einen Abkömmling von Tortolla zu einem Nemesiskristall. Falls Ihr Euren Begleiter verliert, meldet Euch bei Garunda Bergkuppe.", completion = "Ah, ja, ja… Die geheime Stärke von Nemesis, zugänglich hier in diesen Höhlen.\n\nWir wissen alles, was wir wissen müssen, {name}. Jetzt ist es Zeit, der Angelegenheit ein Ende zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25916] = { id = 25916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25917] = { id = 25917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Allianzsklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Allianz in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25918] = { id = 25918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Pikse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Admiral Dvorek bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25919] = { id = 25919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Kapitän Taylor lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht finden Eure Waffen ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25920] = { id = 25920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Valoren verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Kapitän Taylor und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25921] = { id = 25921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Südosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten.", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Kapitän Taylor hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25922] = { id = 25922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Kapitän hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Dem Licht sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25923] = { id = 25923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Nemesis", description = "Euer Schildkrötenfreund kann diese neu gefundene Macht nutzen, um Euch beide für einen kurzen Augenblick unverwundbar zu machen. Ihr könnt Euch also in Euren \"Panzer\" verkriechen, um Nemesis' schlimmsten Zorn zu entgehen. Ruft dazu einfach dieses Totem herbei.\n\nDas ist alles, was ich für Euch tun kann. Ihr und ein Abkömmling von Tortolla müsst gemeinsam Nemesis besiegen, ein für alle Mal. Vernichtet den Usurpator!\n\nFalls Ihr Euren Schildkrötenfreund verliert, kehrt zu mir zurück.", sourceObjective = "Benutzt das Totem von Tortolla, um einem Abkömmling von Tortolla dabei zu helfen, Nemesis zu besiegen. Falls Ihr Euren Schildkrötenfreund verliert, sprecht mit Garunda Bergkuppe.", completion = "Der Usurpator ist nicht mehr!\n\nDer Schattenhammer hat davon geträumt, sich sein eigenes Pantheon von Göttern zu schaffen, die über Land, Meer und Luft herrschen. Doch mit Eurer Hilfe wurden sie alle vernichtet. Wir müssen sofort Tortolla davon berichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25924] = { id = 25924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht ruft", description = "Hört zu, {race}!\n\nAn der Küste der Östlichen Königreiche ist eine neue Landmasse aufgetaucht! Eine wichtige Schlacht um die Kontrolle dieser Insel ist bereits im vollen Gange.\n\nWenn wir hier gewinnen, ist Sturmwind komplett unverteidigt!\n\nJetzt ist die Zeit, um zuzuschlagen!\n\nMeldet Euch sofort an den Docks, damit man Euch zur Schlacht bringt.\n\nAll unsere Kriegsschiffe befinden sich bereits im Kampf, also werdet Ihr ein Söldnerboot nehmen, das vom Kriegshäuptling selbst angeheuert wurde.", sourceObjective = "Fahrt mit dem Söldnerboot zur Schlacht.", completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25925] = { id = 25925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'darahs Rache", description = "Wir müssen versuchen, Kontakt zum Weitblicktal im Süden herzustellen. Unsere darnassischen Glevenwerfer stehen Euch zur Verfügung, {name}. Schlagt mit ihnen eine Schneise in die anrückenden Hordenstreitkräfte und räumt einen Weg ins Weitblicktal frei.\n\nHoffentlich ist es noch nicht zu spät, um das Tal zu retten. Sollte das Weitblicktal unversehrt sein, dann sucht dort nach Hierophant Malyk und informiert ihn über unsere Lage.", sourceObjective = "Tötet 20 Soldaten der Horde und zerstört 3 Verwüster von Krom'gar im Kriegsnarbental.", completion = "Wir haben die Explosion der Bombe beobachtet. Was für eine furchtbare Zerstörung... Das Weitblicktal ist unversehrt, was immer das auch nutzen mag. Allerdings wissen wir nicht, wohin wir fliehen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25926] = { id = 25926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modernder Hass", description = "Die Morastbestien im Westen sind nicht meine Brüder... sie sind Symptome der gestörten Erde, eine modernde, Gestalt gewordene Verderbtheit.\n\nIhr würdet es nicht verstehen... sie nehmen die Gestalt meines Volkes an, sind jedoch mit verrottenden Sporen durchsetzt. Sie vertreiben das blühende Leben aus dem Sumpf. Sie nehmen alles und lassen nur Verderbtheit zurück. Nichts bleibt zurück! Nichts!\n\nTröstet mich, {race}. Tötet die Morastbestien und reinigt das Land. Vielleicht bringt mir das Frieden.", sourceObjective = "Tötet 10 modernde Morastbestien.", completion = "Ahhh... ja. Der Sumpf leidet weniger als zuvor.\n\nEs gibt jedoch noch mehr Bedrohungen. Sie lauern. Ich kann sie sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25927] = { id = 25927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Bedrohung", description = "Die Flammen bedrohen mich schon seit langer Zeit... zu langer Zeit... aber es sind keine kleinen mehr, nicht mehr nur noch Funken...\n\nDie Felder brennen! Die Hügel und Hochlande schreien, {race}, sie schreien. Die Elementare, die hierher gebracht wurden, lassen nur Tod zurück.\n\nDas darf nicht so weitergehen. Haltet sie auf. HALTET SIE AUF! Vernichtet die Flammenboten...", sourceObjective = "Tötet 8 zügellose Feuerelementare.", completion = "Ja... die Flammen vergehen. Nun herrscht Friede. Das Land findet Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25928] = { id = 25928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Triumph", description = "Ich werde die Abkömmlinge von Tortolla hier heraus begleiten und dieses verfluchte Portal versiegeln.\n\nIch überlasse es Euch, Tortolla von unserem Sieg zu berichten. Tretet einfach wieder durch das Flammentor. Der Ahn wird begeistert sein!", sourceObjective = "Geht erneut durch das Flammentor und kehrt zu Tortolla auf der Verbrannten Ebene auf dem Hyjal zurück.", completion = "Ihr wart in den Feuerlanden?\n\nNemesis ist tot?\n\nAlso ist es vorbei.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25929] = { id = 25929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetauglich", description = "Grüße, {class}. Ich bin Erunak, einer der Überlebenden dieses Unglücks.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga durchstreifen die Gewässer und greifen alles an, was noch am Leben ist.\n\nIhr seid an die hiesigen Bedingungen noch nicht ausreichend angepasst, um zu überleben, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Euch dabei helfen wird, Euch an die neue Umgebung zu gewöhnen.", sourceObjective = "Sammelt 3 Salzwasserseesterne und ein Tritonshorn am Meeresgrund im Verhängnis der Legion.", progress = "Konntet Ihr alle Gegenstände finden, die ich brauche, {race}?", completion = "Bitteschön, {class}. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25930] = { id = 25930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talstürmer", description = "Man hat mir erzählt, dass das Verbrannte Tal vor dem großen Umbruch eine Mulde war, ohne Zugang zum Meer. Doch wenn man nun nach Süden blickt, wird deutlich, dass das Verbrannte Tal längst kein Tal mehr ist, sondern ein Gebiet mit großer vulkanischer Aktivität.\n\nSalsbury hat ein Gerät konstruiert, mit dem wir den Vulkan erklimmen können. Benutzt es, um zum Gipfel zu gelangen. Findet heraus, was dort vorgeht.\n\nIch werde mit dem Gnomcordergerät, das Salsbury mir freundlicherweise geschenkt hat, in Kontakt bleiben.", sourceObjective = "Erklimmt mit Salsburys Raketenpack den Vulkan im Verbrannten Tal.", completion = "<Der Gnomcorder knistert vor Energie.>\n\nSeid Ihr da, {name}? Anscheinend seid Ihr mitten in einen Drachenhort geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25931] = { id = 25931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Seldarria", description = "<Der Gnomcorder summt.>\n\nSeid sehr vorsichtig, {name}. Weckt bloß nicht den schwarzen Drachen auf.\n\nSeht Euch um. Wenn dies ein Nest ist, dann sollte es in der Nähe schwarze Dracheneier geben. Sucht das Gebiet nach Eiern ab und zerstört alle, die Ihr seht.\n\nKehrt zu mir zurück, wenn Ihr Seldarrias Eier gefunden und zerstört habt.\n\nMöge Goldrinn über Euch wachen.", sourceObjective = "Zerstört 5 Eier von Seldarria.", completion = "Ein durchschlagender Erfolg! Es ist vielleicht nur ein kleiner Sieg über die Brut von Todesschwinge, aber wenigstens ein Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[25932] = { id = 25932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Nacht ein Überfall", description = "Die Berichte, die ich Hauptmann Tharran schicke, spiegeln das Ausmaß des Ärgers, den uns die Frostmähnen bereiten, nicht richtig wider. Euer Angriff auf das Dorf hat etwas Druck von uns genommen. Die Überfälle finden immer noch häufig statt, aber es gibt nicht mehr so viele Trolle wie früher.\n\nTrotzdem sind meine Männer erschöpft. Die Moral sinkt. Würdet Ihr uns im Kampf gegen die Frostmähnenräuber unterstützen? Sie können jederzeit auftauchen.", sourceObjective = "Helft Unteroffizier Flinthammer und seinen Gebirgsjägern, das Gehöft Bernruh gegen die Frostmähnenräuber zu verteidigen.", progress = "Wir sind froh, dass Ihr uns unterstützt, {name}.", completion = "Dank Eurer Hilfe ist es uns gelungen, die Räuber deutlich zu schwächen. Solche Verluste haben sie seit Beginn der Überfälle nicht mehr erlitten. Wir müssen diesen Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25933] = { id = 25933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Steinbruch", description = "Ich möchte Euch noch einmal für Eure Hilfe danken, {name}.\n\nMein Cousin hat früher in den Minen unter dem Steinbruch Gol'Bolar gearbeitet, aber seit die Troggs dort eingedrungen sind und die Kontrolle übernommen haben, geht das nicht mehr. Der Steinbruch und sein Lager liegen südöstlich des Gehöfts. Würdet Ihr Euch dort bei dem Großknecht melden und herausfinden, ob man etwas unternehmen kann?", sourceObjective = "Sprecht mit Großknecht Steinbraue im Steinbruch Gol'Bolar.", completion = "Unteroffizier Flinthammer? Der Name sagt mir nichts, aber einer der Minenarbeiter heißt Flinthammer. Er gehört zu den Glücklichen, die aus der Mine fliehen konnten, aber die meisten anderen sind dort unten eingeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25934] = { id = 25934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltneuheit: Gnomgen", description = "Guten Tag, Bürger, ich möchte mich Euch vorstellen. Ich bin Salsbury, bald der welterste Gnomgen. Malyk hat mir versichert, dass er mir nach Beendigung meiner Arbeit das Geschenk des Worgen machen wird.\n\nSo, da wir uns jetzt kennen, möchte ich eine Bitte äußern!\n\nSüdlich von hier, im Verbrannten Tal, treiben neu erschaffene Feuerelementare ihr Unwesen. Ich brauche dringend ein seltenes flammendes Herz des Feuers von einem der Unholde. Beschafft es für mich, dann komme ich dem Leben eines Gnomgen einen Schritt näher!", sourceObjective = "Beschafft 1 flammendes Herz des Feuers.", progress = "Habt Ihr das flammende Herz des Feuers bekommen?", completion = "Hervorragend. Damit kann ich meine letzte Aufgabe beenden und hoffentlich die Wolfsform bekommen!\n\n<Salsbury heult.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25935] = { id = 25935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Welpen", description = "Ah, ein Neuankömmling! Gut, dass Ihr hier seid <Junge/Schwester>! Die Welpen sind hungrig, aber uns ist die Nahrung ausgegangen.\n\nZum Glück lieben sie Drachenfleisch, was es in rauen Mengen im Verbrannten Teil südlich von hier gibt.\n\nSeid ein <guter Junge/gutes Mädchen> und besorgt mir ein paar Pfund Schwarzdrachenwelpenfilet.", sourceObjective = "Beschafft 6 Schwarzdrachenwelpenfilets.", progress = "Beeilt Euch, {name}, die Welpen sind hungrig!", completion = "Hervorragend. Die Hunde werden gut zu fressen bekommen und unseren Außenposten wochenlang verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25936] = { id = 25936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ich Euch, so Ihr ihnen", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", sourceObjective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Krieger wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25937] = { id = 25937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unermessliche Reichtümer", description = "In dem Steinbruch wurde nicht nur geschürft. Ich leitete ein Ausgrabungsteam der Forscherliga. Wir suchten nach wertvollen alten Artefakten.\n\nMir gelang die Flucht, aber meine Kollegen hielten sich tiefer in der Mine auf und überlebten den ersten Angriff der Troggs nicht.\n\nSie waren sehr stolz auf ihre Arbeit und riskierten ihr Leben, um mehr über unsere Geschichte herauszufinden. Wenn Ihr in die Minen geht, dann nehmt diese Spitzhacke mit. Vielleicht findet Ihr ja etwas in den Stollen, die von den Ausgräbern begonnen wurden.", sourceObjective = "Bergt 8 gefrorene Artefakte aus der Mine des Steinbruchs Gol'Bolar.", progress = "Habt Ihr dort unten Artefakte gefunden?", completion = "Ich danke Euch für die Bergung dieser Artefakte. Ich werde dafür sorgen, dass sie im Museum von Eisenschmiede ausgestellt werden, zusammen mit der Geschichte derer, die bei ihrer Bergung ums Leben kamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25938] = { id = 25938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Desolace", description = "Ich habe eine verstörende Nachricht aus Nijelspitze in Desolace erhalten. Der große Umbruch hat anscheinend neue Probleme mit sich gebracht, auf die sie nicht vorbereitet waren. Mehr weiß ich nicht.\n\nMeldet Euch bei Offizierin Jankie in Desolace. Sie wird Euch den Weg nach Nijelspitze weisen.\n\nViel Glück, {name}.", sourceObjective = "Meldet Euch bei Offizierin Jankie in Tethris Aran in Desolace.", completion = "Halt, Fremder!", sourceObjectiveStatus = "unverified-source-field" }
quests[25939] = { id = 25939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerteufel", description = "Die Elementare, die auf dem Hügel der Düsterschmiede randalieren, stecken das Land unter sich in Brand. In einem Sumpf wie diesem findet das Feuer im tiefen Moos und Torf ausreichend Nahrung.\n\nLöscht die Feuer, bevor sie sich ausbreiten. Nehmt diese Blume... sie wurde mit dem Regen der Natur gesegnet und wird Euch ermöglichen, die Feuer zu löschen.\n\nIhre Blüten könnten sich außerdem als nützlich gegen die Elementare erweisen.", sourceObjective = "Löscht 7 Moorfeuer mit der gesegneten Flutlilie.", completion = "Ihr habt nicht nur das Land vor weiterem Leid bewahrt, sondern uns auch geholfen, den Sumpfwächter zu besänftigen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25940] = { id = 25940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Gefecht am Rauschenden Hain", description = "Möglicherweise habe wir jetzt eine Chance, die Flammen dank Eurer Arbeit in dem Inferno zu besiegen.\n\nDennoch sind weitere Wildtiere bedroht. Hüter Taldros rannte Richtung Norden durch die Flammen zum Rauschenden Hain.\n\nSeht, ob Ihr ihm helfen könnt!", sourceObjective = "Meldet Euch bei Hüter Taldros im Rauschenden Hain auf dem Hyjal.", completion = "Die Flammen verschlingen den Wald!", sourceObjectiveStatus = "unverified-source-field" }
quests[25941] = { id = 25941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rast für die Erschöpften", description = "Ihr habt Eure Aufgabe gut gemacht, {race}, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut, was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", sourceObjective = "Sprecht mit Legionär Nazgrim.", completion = "Ich verstehe, {race}.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25942] = { id = 25942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "Viele gute Krieger mussten heute ihr Leben lassen.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", sourceObjective = "Tötet 8 Räuber des Zin'jatar im Verhängnis der Legion.", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um uns die nötige Zeit zu verschaffen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25943] = { id = 25943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege gehen durch den Magen", description = "Wenn ich diese Orcs für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Mampf, kein Kampf.\n\nDiese Krieger sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass die Naga angreifen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", sourceObjective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", progress = "Habt Ihr Nahrung für die Truppen, {race}?", completion = "Ein leckerer Happen.\n\nBald sind wir wieder kampfbereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25944] = { id = 25944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Horde alte Kleider", description = "In unserem Kampf gegen das Ertrinken waren meine Orcs und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich glaube ihm.\n\nWenn wir siegen wollen, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen.\n\nEs sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks hier und im Norden liegen.\n\nSchnell, {race}. Der Feind könnte jeden Moment eintreffen.", sourceObjective = "Sammelt 5 Äxte von Orgrimmar, 5 Brustplatten von Orgrimmar und 5 Helme von Orgrimmar am Meeresboden oder von Strauchdieben der Gilblin im Verhängnis der Legion.", progress = "Konntet Ihr unsere Ausrüstung zusammensammeln, {race}?", completion = "Das habt Ihr gut gemacht, {race}.\n\nUnsere Überlebenschancen steigen stetig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25945] = { id = 25945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben hier nur eine Aufgabe, vielleicht auch zwei...", description = "Ihr seid jetzt in Höllschreis Armee, {name}, und in Höllschreis Armee treten wir anderen in den Hintern und sind verdammt nachtragend. Die Zeiten, in denen Leute auf den Straßen Orgrimmars verhungerten, während wir Verträge mit den Elfen schlossen, sind vorbei. Wir holen uns jetzt, was wir brauchen. Kalimdor gehört der Horde!\n\nDie Allianz versucht bei jeder Gelegenheit, unsere Expansion aufzuhalten. Diesen Schweinslutschern gehört bereits ein Großteil der Östlichen Königreiche, aber das reicht ihnen nicht!\n\nOberanführer Krom'gar will mehr Truppen ins Steinkrallengebirge verlegen. Schließt Euch der Karawane westlich von hier an. Geht!", sourceObjective = "Reist mit dem Wagen von Krom'gar zum Bruch im Steinkrallengebirge.", completion = "Solange Ihr im Steinkrallengebirge seid und als ein Soldat Krom'gars kämpft, werdet Ihr Uniform tragen! Ist das klar? HÖRT Ihr mich, Grunzer? Wenn ich Euch ohne Höllschreis geliebten Waffenrock sehe, werde ich Euch so heftig in den Hintern treten, dass Ihr Schnürsenkel ausspuckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25946] = { id = 25946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ScHELMenstück", description = "<Dieser Helm und das passende Zubehör sind mit dem Siegel von Sturmwind gekennzeichnet. Er stammt ohne Zweifel von einem Allianzschiff, dass ein ähnliches Schicksal wie Euer Schiff erlitten hat.>\n\n<Wenn Ihr den Helm genauer betrachtet, fällt Euch auf, dass er viel zu gut verarbeitet und stabil ist, um zu einer normalen Tauchausrüstung zu gehören. Vielleicht weiß Nazgrim ja, was es damit auf sich hat...>", sourceObjective = "Bringt die Kampfschwimmerausrüstung der Allianz zu Legionär Nazgrim in der \"Ewiger Kreislauf\".\n\nBereitgestellter Gegenstand:", completion = "Blut und Donner!\n\nDas ändert alles, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25947] = { id = 25947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer es findet, darf es behalten", description = "Ich erkenne diesen Helm, {race}. Es war klug von Euch, ihn mir zu bringen.\n\nDie Allianz hat eine Spezialeinheit, die für Erkundungen und Kampfeinsätze unter Wasser ausgebildet und ausgerüstet wurde.\n\nWie es scheint, haben sie in dieser Gegend weitaus mehr vor, als sich gegen unseren Angriff zu verteidigen.\n\nEs muss da unten noch mehr davon geben. Wenn Ihr sie findet, könnte sich das Blatt für unseren Vorposten schnell wenden.", sourceObjective = "Sammelt 5 Teile einer Kampfschwimmerausrüstung von Sturmwind.", progress = "Konntet Ihr weitere Teile der Allianzausrüstung finden, {name}?", completion = "Gut gemacht!\n\nJetzt sind wir so bereit wie nie, uns den Naga entgegenzustellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25948] = { id = 25948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gewartet!", description = "Es ist an der Zeit, {class}.\n\nWir sind so bereit wie es nur geht!\n\nIch werde zu den Truppen sprechen und dann schwimmen wir ins Meer, dem Schicksal entgegen.", sourceObjective = "Sprecht mit Legionär Nazgrim an Bord der \"Ewiger Kreislauf\".", completion = "Keine Zeit für Ansprachen.\n\nAuch gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[25949] = { id = 25949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut und Donner!", description = "Die Zeit ist gekommen, um uns zur Wehr zu setzen, {race}.\n\nWir werden dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass dieser Nagaabschaum es sich zweimal überlegt, bevor er sich ihm erneut nähert!\n\nFür die Horde!", sourceObjective = "Helft Legionär Nazgrim dabei, die \"Ewiger Kreislauf\" zu verteidigen.", completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[25950] = { id = 25950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <der/die> berühmte {name}, von <dem/der> alle reden? Schön, Euch kennenzulernen, Schätzelchen. Kommt, lasst mich mal ein Auge riskieren.\n\nGenug Geplauder, kommen wir zur Sache, ja? Ich will, dass Ihr für mich nach Nordwesten zu der Frontlinie der Sira'kess schwimmt und den Naga ordentlich einen vor den Latz knallt.\n\nNix Wildes. Die sind nur auf Streit aus und den sollen sie kriegen!", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Nicht schlecht, Herr Specht, {name}! Das wird den Schlangen zeigen, wo der Hammer hängt und wer hier der Boss ist!\n\nUnd jetzt zu dem versprochenen Umtrunk - lieber einen Branntwein aus Zuckerrohr oder einen guten Traubensaft?", sourceObjectiveStatus = "unverified-source-field" }
quests[25951] = { id = 25951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlussurteil", description = "Geht zur Brücke im Osten, schnell. Lady Naz'jar und der Tiefenlord sollten sich dort mit den verbleibenden Streitmächten aufhalten.\n\nFolgt wie immer den Anweisungen unserer Lady. Haltet die Brücke, bis wir das Ritual beenden können.\n\nSobald unsere Verbündeten eintreffen, sind die Kvaldir dem Untergang geweiht.", sourceObjective = "Haltet die Brücke auf der Terrasse von Quel'Dormir, bis Lady Sira'kess' Verbündete eintreffen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Bleibt an unserer Seite, Kriegsmaid. Am heutigen Tage werden wir nicht fallen.", completion = "Ich könnte mir keine fähigere Kriegsmaid wünschen als Euch. Ihr habt Euch heute große Ehre verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25952] = { id = 25952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", sourceObjective = "Tötet 10 Patrouillen der Azsh'ir.", completion = "Ausgezeichnete Arbeit, {class}.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25953] = { id = 25953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", sourceObjective = "Zerstört 8 Überwacher der Azsh'ir.", completion = "Gut gemacht, {name}. Und genau rechtzeitig. Der Hauptmann hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25954] = { id = 25954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vergangenheit", description = "Hört mal... {name}, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nZu der Zeit als Azshara regierte, war dies eine königliche Stadt der Elfen. Tief in dieser Stadt liegen die Schlüssel zu lange verschollenem Wissen und Artefakten von unermesslichem historischen Wert. Bitte, haltet doch nach interessanten Gegenständen Ausschau, wenn Ihr ohnehin schon in der Stadt seid.", sourceObjective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der Großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25955] = { id = 25955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Standort", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", sourceObjective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Südosten der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, {class}.\n\nEs klingt so, als ob das Gebäude nördlich der Gärten einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25956] = { id = 25956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zur Ruhestatt der Legion.", progress = "Ja, {class}?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25957] = { id = 25957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Hauptmann es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Hauptmann und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25958] = { id = 25958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Hauptmann hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er trifft dort Vorbereitungen für eine Art Angriff auf die Naga.\n\nIhr solltet sofort zu ihm gehen und ihn über das Ausmaß dessen, was Ihr beobachtet habt, unterrichten. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferdchen. Es kennt den Weg.", sourceObjective = "Sprecht mit Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir.\n\nBenutzt das Seepferdchen von Wellensprecherin Tulra, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25959] = { id = 25959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden, unter der Terrasse, ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südwestlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25960] = { id = 25960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Hauptmann gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Bringt ihnen mehr Armbrustbolzen, um uns etwas Zeit zu verschaffen.", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Horde auf den Felsvorsprüngen um das nördliche Ende der Gärten von Quel'Dormir.", completion = "Ihr seid wahrscheinlich der zuverlässigste {race}, den ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25961] = { id = 25961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spannende Ablenkung", description = "Ha! Habt Ihr gesehen, wie der Hauptmann mir böse Blicke zuwirft und mich herablassend behandelt? Ich habe offen gestanden alle Hoffnung verloren, dass er versteht, welch gute Gelegenheit die Ruinen uns bieten, diesem ganzen Schlamassel etwas Positives abzugewinnen.\n\nIch habe gehofft, dass Ihr wieder auftauchen würdet. Ihr scheint <der Einzige zu sein, dem/die Einzige zu sein> der; ich vertrauen kann. Ich habe ein paar Tafeln wie diese verstreut in den Ruinen in der Nähe gesehen und ein Abpausset zusammengestellt, um sie zu abzuschreiben. Habt Ihr Lust?", sourceObjective = "Schreibt die 4 Tafeln der Hochgeborenen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[25962] = { id = 25962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Ich war schon überall. Habe alle möglichen Dinge in die Luft gejagt. Ich dachte, ich hätte vielleicht Probleme damit, den neusten Entwicklungen zu folgen. Ihr wisst schon, wegen dem Wasser und so, aber es ist alles nur eine Frage der Inspiration.\n\nIch habe etwas gefunden, das explosiv genug ist, um Bomben daraus zu bauen. Unter der Terrasse im Südwesten hängen ein paar Tangblasen herab. Normalerweise speichert Tang Gas, das ihn zum schweben bringt, doch dieses schwere Gas ist ganz anders. Es bringt ihn dazu, hängen zu bleiben. Außerdem eignet es sich perfekt für Explosionen.\n\nKönnt Ihr mir etwas davon sammeln?", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südwestlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25963] = { id = 25963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der südlichen zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Fiasco Siedefeix, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", completion = "Ihr habt Euch da oben großartig geschlagen, Soldat! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25964] = { id = 25964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25965] = { id = 25965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Hauptmann zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben.\n\nEine ihrer größten Gruppen befand sich im nordwestlichen Teil dieser runden Terrasse und die andere ein wenig weiter im Norden, in dem kleinen Tunnel, ebenfalls auf der mittleren Ebene der Ruinen.\n\nInterressiert an ein wenig Arbeit als Kundschafter?", sourceObjective = "Späht den Rand der runden Terrasse im Nordwesten und den Tunnel unter der Haupttreppe im Norden aus. Beides befindet sich auf der Terrasse von Nar'shola, in der mittleren Ebene der Ruinen.", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25966] = { id = 25966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25967] = { id = 25967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt das Seepferdchen von Wellensprecherin Tulra, um zu Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Schön, Euch in einem Stück zu sehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25968] = { id = 25968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Toldrek und Fiasco sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Wir werden hier nicht viel länger aushalten. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Fiasco Siedefeix auf dem Biel'arangrat.", completion = "Schaut Euch an, Ihr seid ein echter Held des Meeres! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Ihr müsst stolz auf Euch sein!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25969] = { id = 25969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Fiasco kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Gilblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Gilblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25970] = { id = 25970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Es ist nicht weit bis zur Oberfläche. Eigentlich alles kein Problem. Doch es ist nicht leicht, Ausrüstung nach da oben zu bringen. Sie ist einfach zu schwer.\n\nAlle Schiffe in der Flotte der Horde sind mit einer Überlebensausrüstung ausgestattet. Ich hatte einen Ballon aus so einer Überlebensausrüstung, aber er musste sich leider den Widrigkeiten geschlagen geben. Ich brauche noch eine Überlebensausrüstung.\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren, die Überlebensausrüstung nicht mitzunehmen. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Horde.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25971] = { id = 25971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Seile und Bomben, das ist alles, was sie enthalten sollten. Der Rest des Krams ist einfach nur Platzverschwendung.\n\nBis auf den Ballon vielleicht. Der kommt uns jetzt gerade gelegen.\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Seile sind nicht optional!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25972] = { id = 25972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Gut gemacht.\n\nToldrek ist bereits nach oben geschwommen, um ihn zu packen. Er macht sich Sorgen um die Strömung und all so was. Er meinte aber, er würde Euch die Ehre überlassen. Netter Kerl - Keine Ahnung, wie er am Leben bleibt.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Horde Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Hordenschiffe.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25973] = { id = 25973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Legionär Nazgrim an der Ruhestatt der Legion zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ihr habt hier unten Euren Wert mehr als deutlich bewiesen. In der Horde ist ein Ehrenplatz für Euch sicher.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25974] = { id = 25974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <dieser/diese> {name}, von <dem/der> alle sprechen? Schön, Euch endlich zu treffen.\n\nNun, genug der Worte. Lasst uns zur Sache kommen. Ihr müsst für mich nach Nordwesten zur Frontlinie der Sira'kess schwimmen und schnell diese Naga erledigen.\n\nNichts Aufregendes. Sie sind auf einen Kampf aus und wir werden ihnen einen bieten. Mit 'wir' meine ich natürlich Euch.", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Sehr gut, {name}! Das wird diesen Naga zeigen, wer hier die Hosen anhat!\n\nAlso, zu unserem Schlückchen. Was mögt Ihr lieber? Rum oder Wein?", sourceObjectiveStatus = "unverified-source-field" }
quests[25975] = { id = 25975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Wir haben unsere ersehnte Verstärkung, aber immer noch keine Ahnung, wie wir sie bezahlen sollen. Und diese Art von Hilfe ist nicht ganz billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für unsere Zwecke zurückzustehlen.", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das sollte vorerst reichen. Wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25976] = { id = 25976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einforderung der Schätze", description = "Blut und Donner! Wir haben unsere ersehnte Verstärkung, aber wir müssen sie leider auch bezahlen. Das wird sicher nicht billig.\n\nAuf dem Tiefenflossengrat im Nordwesten gibt es ein paar schleimige Gilblins, die die verschiedensten Schätze zusammengerafft haben. Es ist an der Zeit, ihnen ein wenig davon für die Horde zurückzustehlen.\n\nHöllschreis Augen ruhen auf Euch, {name}!", sourceObjective = "Sammelt 6 Stück Tiefenflossenbeute.", progress = "Wie viel Beute konntet Ihr zurückfordern, {name}?", completion = "Das ist ganz schön viel. Und wir wissen ja, wo es bei Bedarf mehr gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25977] = { id = 25977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Schlangen sind hinter unserer Armee her. Geht nach Nordwesten zum Tiefenflossengrat und steckt dem Futzi, den sie ihren Boss nennen, ein bisschen Holz zwischen die Rippen.\n\nWenn sie das sehen, werden sie Angst bekommen und abhauen mit dem Schwanz zwischen den Bei... ach nee, Beine haben sie ja gar keine.", sourceObjective = "Rammt die Standarte der Allianz in Tiefenrufer Azrajars Leichnam.", completion = "Saubere Arbeit! \"O'zapft is der General!\", würde ich mal sagen.\n\n<Der Leutnant schüttelt mit dem Kopf und grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25978] = { id = 25978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Eis eingeschlossen", description = "Khurgorn sagt, der Kataklysmus habe das Gleichgewicht der Elemente auf der ganzen Welt erschüttert. Der Helmsbettsee im Süden war einmal wunderschön und ruhig, doch nun wimmelt es dort von wütenden Wasserelementaren. Als sie begannen, den See zu verlassen, schickte ich Truppen dorthin, um sie abzulenken, aber die meisten wurden in Eisblöcken eingefroren.\n\nWenn wir sie befreien können, werden sie sich wahrscheinlich erholen. Ich kann niemanden für eine zweite Expedition zum See entbehren. Würdet Ihr es versuchen?", sourceObjective = "Öffnet sechs eisige Gräber, um die gefrorenen Gebirgsjäger am Helmsbettsee zu befreien.", completion = "Ihr habt es geschafft! Die Gebirgsjäger kehren ins Lager zurück. Unsere Sanitäter werden viel zu tun haben. Wir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25979] = { id = 25979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glättet die Wogen", description = "Die Elemente sind aufgewühlt, {class}. Der Kataklysmus hat die schlafenden Wassergeister im Helmsbettsee südlich von hier geweckt. Sie sind wütend, verwirrt und nicht gewillt, sich meine Bitten anzuhören.\n\nIch habe alles versucht, um sie zu beruhigen und davon zu überzeugen, die Gebirgsjäger des Unteroffiziers nicht mehr anzugreifen.\n\nIch sage das nur ungern, aber uns bleibt keine andere Wahl -- wir müssen die Elementare töten.", sourceObjective = "Tötet 6 Woger des Helmbettsees am Helmbettsee.", completion = "Es fällt mir nicht leicht, Gewalt gegen die Elemente anzuwenden, deren Macht ich benutze, aber manchmal gibt es keinen anderen Weg. Wir sind zuerst den Bewohnern Dun Moroghs verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25980] = { id = 25980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standartenmäßiger Tag für Azrajar", description = "{name}, die Naga sind hinter unseren Streitmächten her. Ihr müsst für mich zurück nach Nordwesten zum Tiefenflossengrat gehen und unsere Standarte in ihren General, Tiefenrufer Azrajar stechen.\n\nSie werden vor Angst davon schwimmen, mit dem Schwanz zwischen den… äh. Na ja, Beine haben sie ja wohl nicht, oder?", sourceObjective = "Rammt die Standarte der Horde in Tiefenrufer Azrajars Leichnam.", completion = "Ihr habt ihn also richtig durchbohrt? Das hätte ich ja zu gerne gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25981] = { id = 25981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Auch eine Art, an Sklaven zu kommen.\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen?", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Wie viele habt Ihr?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Stinken nur ganz schön.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25982] = { id = 25982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind gar keine Masken", description = "{name}, da draußen sind dämonische Tintenfische, die die Köpfe der Gilblins fressen und ihre Körper übernehmen! Wir müssen verhindern, dass sie hierher kommen!\n\nKönntet Ihr nach Nordwesten in den Tiefenflossengrat oder die Frontlinie der Sira'kess schwimmen und mir ein paar von diesen Gnadenlosen bringen? Bevorzugt tote Exemplare, schätze ich.", sourceObjective = "Sammelt 6 Köpfe eines Gnadenlosen.", progress = "Was stinkt hier so?", completion = "Ach, die sind furchtbar hässlich, aber sie sehen eigentlich ganz harmlos aus. Eigentlich. Irgendwie sind sie fast schon niedlich.\n\nLasst mich nur noch die Gilblinüberreste entfernen. Ich habe eine Idee…", sourceObjectiveStatus = "unverified-source-field" }
quests[25983] = { id = 25983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "Wir müssen diese Informationen zu Kapitän Taylor am Kap bringen. Er befindet sich im Nordwesten mit Erunak Steinsprecher und den Mitgliedern des Irdenen Rings.", sourceObjective = "Sprecht mit Kapitän Taylor am Kap in Vashj'ir.", completion = "Das sind verstörende Neuigkeiten, doch ich glaube, dass unsere Freunde vom Irdenen Ring einen Plan haben.\n\nUnd jetzt, da Ihr hier seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[25984] = { id = 25984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kap", description = "{name}, ich möchte, dass Ihr diese Informationen zu Legionär Nazgrim am Kap bringt. Er befindet sich im Nordwesten mit Erunak Steinsprecher und diesen Leuten vom Irdenen Ring.", sourceObjective = "Sprecht mit Legionär Nazgrim am Kap in Vashj'ir.", completion = "Ich würde meinen Ohren nicht trauen, wenn nicht Ihr der Überbringer dessen wärt, was dieser lästige Goblin zu sagen hat. Das ist in der Tat beunruhigend, aber ich glaube, dass unsere Freunde vom Irdenen Ring einige Ideen haben.\n\nUnd wo Ihr nun hier seid…", sourceObjectiveStatus = "unverified-source-field" }
quests[25985] = { id = 25985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen über dem Hyjal", description = "{name}, ist es wahr, dass Ihr versuchen werdet, mit den Ahnen zu sprechen?\n\nSüdwestlich von hier befindet sich der Schrein von Aviana, der Mutter aller fliegenden Lebewesen. Dort lebt meine Lieblingslehrerin, Choluna. Ich habe noch nie jemanden kennengelernt, der so eins mit den Geistern dieser Welt war. Ihr könntet viel von ihr lernen!\n\nWegen der kürzlichen Angriffe ist der Schrein von der Außenwelt abgeschnitten. Aber aus der Luft könnt Ihr ganz einfach dorthin gelangen. Haltet nach dem größten Baum auf dem Hyjal Ausschau. Viel Glück!", sourceObjective = "Findet Choluna am Schrein von Aviana auf dem Hyjal.", completion = "Oh, Tiala schickt Euch? Was für eine herausragende Schülerin. Sie wird noch Großartiges erreichen.\n\nObwohl ich in Euch sogar noch mehr Potenzial spüre.\n\nBitte, bleibt doch eine Weile bei unserem Schrein. Es gibt viel zu tun, aber mit einem beunruhigten Gemüt lässt es sich kaum bewältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25986] = { id = 25986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am See", description = "Ihr wart eine große Hilfe bei der Sicherung der Minen und der Rettung der gefangenen Minenarbeiter.\n\nEs wird den Senat freuen, dass Ihr und Hauptmann Tharrans Gebirgsjäger Fortschritte bei der Sicherung Dun Moroghs gemacht habt.\n\nMich besorgt allerdings, dass ich keine Berichte von Unteroffizier Bahrum und seiner Abteilung erhalten habe. Sie wurden nach Osten geschickt, auf die Straße, die zum Helmsbettsee führt. Dort sollten sie einen kleinen Außenposten errichten. Würdet Ihr zu Bahrums Posten reisen und nach dem Unteroffizier sehen?", sourceObjective = "Sprecht mit Unteroffizier Bahrum an Bahrums Posten.", completion = "Gut, dass der Senator nicht allein hierhergekommen ist. Es ist gefährlich hier. Wir werden all die Hilfe brauchen, die wir kriegen können, um die Lage unter Kontrolle zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25987] = { id = 25987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "He, {name}! Ich habe eine tolle Idee für eine Verkleidung. Nehmt einen dieser gnadenlosen Wasauchimmers und setzt ihn Euch auf den Kopf.\n\nWas kann dabei schon schiefgehen?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Was ist passiert? Das Ding war wohl nicht ganz tot! Vielleicht sollte ich einfach bei den mechanischen Dingen bleiben.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will sie keinesfalls in meiner Nähe haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25988] = { id = 25988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt es auf", description = "Ich habe eine tolle Idee für eine Verkleidung, aber ich brauche Eure Hilfe dabei, {name}. Nehmt einen dieser gnadenlosen Leichname und setzt ihn Euch auf den Kopf.\n\nIch weiß, ich weiß, aber es ist tot. Was kann dabei schon schiefgehen, außer dass Ihr ein, zwei Tage übel riecht?\n\nSeid Ihr bereit, ihn aufzusetzen?", sourceObjective = "Beobachtet, was passiert, wenn Ihr einen Gnadenlosen auf Euren Kopf setzt.", completion = "Mein Fehler. Ich heiße nicht umsonst \"Fiasco\". Ich hätte wissen sollen, dass es nicht ganz tot ist, als es gezuckt hat.\n\nIhr habt davon eine Vision bekommen? Wie Ihr uns alle tötet?! Das klingt nicht gut.\n\nNun, dieser Kerl vom Irdenen Ring, Erunak Steinsprecher, will jedenfalls alle Exemplare haben. Ich kümmere mich darum, dass er sie bekommt. Ich will nicht, dass sie hier alles vollstinken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25989] = { id = 25989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25990] = { id = 25990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25991] = { id = 25991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Hordesklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Horde in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25992] = { id = 25992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Pikse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Hauptmann Übeldorn bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25993] = { id = 25993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Legionär Nazgrim lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht findet Euer Schwert ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25994] = { id = 25994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Tulra verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Legionär Nazgrim und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25995] = { id = 25995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Nordosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten. Höllschreis Augen ruhen auf Euch!", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Legionär Nazgrim hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25996] = { id = 25996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Legionär hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Höllschrei sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25997] = { id = 25997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimtücke der Dunkeleisenzwerge", description = "Eine Gruppe Dunkeleisenspione hat Eisenbands Truppenlager im Süden, hinter dem Helmsbettsee übernommen. Die Gebirgsjäger wären normalerweise in der Lage, sie aus Dun Morogh herauszuhalten, aber es herrscht gerade Chaos.\n\nDie Dunkeleisenzwerge wären Narren, wenn sie das nicht zu ihrem Vorteil nutzen würden. Wir müssen herausfinden, was sie planen und sie aufhalten, bevor sie Schaden anrichten.\n\nKönntet Ihr versuchen herauszufinden, was sie in Eisenbands Truppenlager machen?", sourceObjective = "Tötet 5 Spione der Dunkeleisenzwerge und erbeutet die Angriffspläne der Dunkeleisenzwerge von Hauptmann Beld in Eisenbands Truppenlager.", progress = "Was haben die Dunkeleisenzwerge vor?", completion = "Ich habe mir schon gedacht, dass sie nicht wegen der Aussicht hier sind.\n\n<Der Unteroffizier betrachtet die Pläne, die Ihr erbeutet habt. Seine Augen weiten sich.>\n\nDas ist ernster als befürchtet! Dies ist nicht nur ein Überfall. Die Dunkeleisenzwerge wollen die Verteidigungsbollwerke von Eisenschmiede lahmlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25998] = { id = 25998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Flugplatz", description = "Laut der Pläne, die Ihr erbeutet habt, planen die Dunkeleisenzwerge einen großangelegten Angriff auf den Flugplatz von Eisenschmiede! Der Rat hat einen Großteil unserer Streitkräfte nach Dun Morogh verlegt. Sie sollen sich dort um die Instabilität, die durch den Kataklysmus entstanden ist, kümmern. Die Verteidigungslinien des Flugplatzes sind geschwächt.\n\nWir müssen Euch so schnell wie möglich zum Flugplatz bringen. Nehmt die Straße zurück nach Westen, in Richtung des Steinbruchs Gol'Bolar und findet Mathel Rostzange. Er sollte eine Flugmaschine für Euch haben. Geht!", sourceObjective = "Steigt in Mathels Flugmaschine im Steinbruch Gol'Bolar.", completion = "Zum Glück seid Ihr hier, {name}. Der Flugplatz wird von Dunkeleisenzwergen angegriffen. Wir halten nicht mehr lange durch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25999] = { id = 25999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schritt für Schritt", description = "Den schmutzigen, nichtsnutzigen Nachtelfen ist es gelungen, unser ganzes Minenfeld auf dem Steinkrallenpass zu entschärfen. Jemand muss dorthin zurückgehen und die Minen wieder scharf machen! Diese Aufgabe ist perfekt für einen wertlosen Grunzer wie Euch geeignet, {name}. Hoffentlich jagt Ihr Euch dabei nicht selbst in die Luft.\n\nUnsere \"Elfentöter\" liegen überall auf dem Steinkrallenpass, unmittelbar nördlich von hier. Nehmt diesen Schraubenschlüssel und macht Euch an die Arbeit, Made.", sourceObjective = "Macht 8 Krom'gar \"Elfentöter\" scharf.", completion = "<Saurboz mustert Euch.>\n\nIhr habt noch alle Gliedmaßen. Das gab's noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26000] = { id = 26000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit Gurrok in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[26001] = { id = 26001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Sprengenieur", description = "Ihr seid wohl doch nicht völlig nutzlos. Vielleicht bewältigt Ihr sogar eine etwas wichtigere Aufgabe.\n\nVor rund zwei Tagen habe ich Sprengenieur Fusselpfiff zur Scherwindmine geschickt. Er sollte sich dort davon überzeugen, dass alles mit der Bombe nach Plan läuft und sich dann wieder hier melden. Zwei Tage und nichts...\n\nBegebt Euch in den Wald südlich von hier und findet ihn. Wenn er Glück hat, ist er tot.", sourceObjective = "Findet Sprengenieur Fusselpfiff.", completion = "Sprengenieur Fusselpfiff ist definitiv tot. Ist vielleicht besser so.\n\nEr scheint eine Notiz in der Hand zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26002] = { id = 26002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne der Allianz", description = "<Ihr zieht die Notiz aus Fusselpfiffs toten Fingern.>\n\nSie wissen Bescheid! Sie wissen von der Bombe. Planen Angriff auf Feste Krom'gar! Ich glaube, sie suchen mich. Werde nicht sterben wie ein Feigling. Ich werde kämpfen.\n\nIch glaube, da kommen sie! Ihre Anführerin ist eine Hochelfenjägerin namens Davinia. Sie sprach von den Angriffsplänen. Rächt mich, indem Ihr sie tötet und Euch die Pläne holt! Ihr Zelt steht östlich von hier, ganz in der Nähe.\n\nMöge Höllschrei über Euch wachen...", sourceObjective = "Erbeutet die Angriffspläne der Allianz von Jägerin Davinia.", progress = "Habt Ihr Fusselpfiff gefunden?", completion = "Verdammt schade... Er war ein guter Goblin.\n\n<Saurboz schüttelt seine Faust.>\n\n{name}, Ihr habt richtig gehandelt. Dank dieser Angriffspläne können wir uns vorbereiten. Ich möchte, dass Ihr die Pläne Oberanführer Krom'gar persönlich übergebt! Es sollte eine Beförderung für Euch drin sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26003] = { id = 26003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehren von den Verlorenen Inseln", description = "In den Wäldern südlich von hier lauern große Gefahren. Sie wimmeln von darnassischen Spähern - Assassinen, die aus Darnassus geschickt wurden, um uns zu töten. Vielleicht können wir den Spieß umdrehen.\n\nAls ich auf den Verlorenen Inseln festsaß, gab mir ein Goblin diese Infrarot-Hitzebrille. Mit ihr kann der Träger die Wärmesignatur bestimmter Kreaturen sehen. Nehmt die Brille und setzt sie in den Wäldern im Süden auf. Auf diese Weise werdet Ihr die Späher leicht entdecken können. Tötet so viele Ihr könnt! Für die Horde!", sourceObjective = "Tötet 12 Späher von Darnassus.", completion = "Gut gemacht, Bruder! Jetzt wissen sie, dass sie sich nicht an die Horde anschleichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26004] = { id = 26004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feste Krom'gar", description = "Feste Krom'gar ist unsere Hauptoperationsbasis im Steinkrallengebirge. Von hier aus überwacht Oberanführer Krom'gar die militärischen Aktionen der Horde in dieser Region. Krom'gar leitet die Berichte aller Ereignisse direkt an den Kriegshäuptling weiter.\n\nDie Angriffspläne, die Ihr uns gebracht habt, beschreiben einen Angriff, der bald gegen die Feste Krom'gar geführt werden soll. Nehmt die Pläne und brecht zur Feste südwestlich von hier auf. Gebt sie dem Oberanführer.\n\nLebt wohl, {name}. Höllschrei wacht wahrlich über Euch.", sourceObjective = "Bringt die Angriffspläne der Allianz zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", progress = "Was hat diese Unterbrechung zu bedeuten? Wieso steht dieser Grunzer vor Oberanführer Krom'gar?", completion = "<Ihr gebt Oberanführer Krom'gar die Pläne.>\n\nHmm. Vielleicht steckt mehr in Euch, als es den Anschein hat. Vielleicht steckt in Euch ein Unteroffizier.\n\nRichtet Euren Blick auf Krom'gars Unteroffizier {name}, Soldaten. Er hat uns vor einem feigen Angriff der Allianz gewarnt. Einem Angriff, den wir NIEDERWERFEN werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26005] = { id = 26005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Kapitän Taylor und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nHexasept hat die hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Kapitän Taylor auf der Voldrins Mut an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es geschafft! Schön Euch zu sehen, {name}.\n\nEs ist ein tolles Gefühl, dem Wasser entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Ich bin mir sicher, dass viele der Jungs nach all den Strapazen alles geben würden, um umzudrehen und nach Hause fahren zu können. Aber wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Haltet Ihr bis zum Ende durch? Ich würde es Euch nicht übel nehmen, wenn Ihr die Nase voll hättet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26006] = { id = 26006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch frischer Luft", description = "Legionär Nazgrim und viele der anderen Überlebenden sind bereits auf dem Weg an die Oberfläche. Ich bin mir sicher, dass viele davon einfach nur nach einem Weg suchen, diesem Ort für immer zu entfliehen, aber wir haben immer noch viel zu tun, wenn wir die Naga an ihrem Einmarsch in die Ebene des Wassers hindern wollen.\n\nZunächst müssen wir uns um das tentakelbewehrte Monster kümmern, das unsere Schiffe zerstört hat.\n\nFiasco hat das hier für Euch zurückgelassen. Sie sollten Eure Reise etwas beschleunigen.", sourceObjective = "Findet Legionär Nazgrim auf der Höllenjuwel an der Oberfläche über den Ruinen von Vashj'ir.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es also in einem Stück geschafft, {class}.\n\nEs ist ein tolles Gefühl, diesem stinkenden Pfuhl entkommen zu sein und wieder über ein paar Ressourcen zu verfügen. Macht es Euch aber nicht zu bequem. Wir haben noch eine schlimme Aufgabe vor uns.\n\nWas ist mit Euch? Hattet Ihr genug Ruhm für einen Tag oder stürzt Ihr Euch wieder in den Kampf, um Höllschrei Stolz zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26007] = { id = 26007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Krieger stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gurrok und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26008] = { id = 26008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Krieger inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Kriegern in der Umklammerung.", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26009] = { id = 26009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchen und zerstören", description = "Die Allianz rückt auf unsere Territorien im Steinkrallengebirge vor. Die Streitkräfte von Nordwacht haben unsere Blockade im Süden durchbrochen und besetzen nun das Scherwindtal westlich von hier. Im Norden werden wir von Nachtelfensoldaten angegriffen. All das muss aufhören!\n\nBegebt Euch ins Steinkrallengebirge und vernichtet alle Allianzsoldaten, die Euren Weg kreuzen. Ihr Tod soll als Warnung dienen.\n\nDas Steinkrallengebirge gehört der Horde!", sourceObjective = "Tötet 20 beliebige Soldaten der Allianz im Steinkrallengebirge.", completion = "Es wird noch viel Blut in dieser Erde versickern, bis der Krieg vorüber ist. Blut der Allianz...", sourceObjectiveStatus = "unverified-source-field" }
quests[26010] = { id = 26010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Die Allianz wird immer unverschämter. Westlich von hier, im Scherwindtal, haben Truppen der Nordwacht ein Lager aufgeschlagen. Zweifellos bereiten sie sich auf den Angriff vor, den Ihr uns gemeldet habt, {name}. So weit wird es nicht kommen!\n\nNehmt diesen Flammenwerfer. Den gleichen Flammenwerfer setzten meine Verbrenner ein, um unsere Feinde aus den Wäldern zu jagen. Zerstört damit die Zelte der Nordwacht. Lasst nur Asche zurück!", sourceObjective = "Zerstört 8 Zelte der Nordwacht mit Krom'gars Flammenwerfer.", completion = "Lok'tar! Allianzschweine!\n\n<Oberanführer Krom'gar spuckt auf den Boden.>\n\nGenießt Euren Sieg, er wird nicht lange währen. Euer Mut hat uns Zeit verschafft, aber mehr nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26011] = { id = 26011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feind der Horde: Marschall Paltrow", description = "Meine Späher haben die Ursache dieses neuesten Fiaskos gefunden: Marschall Paltrow. Er kommandiert das Vorauslager der Nordwacht im Scherwindtal westlich von hier. Eliminiert ihn. Damit entfernt Ihr einen wichtigen Feldkommandanten der Allianz aus der Gleichung.\n\nPaltrow muss sterben, {name}.", sourceObjective = "Tötet Marschall Paltrow.", completion = "Habt Ihr verdächtige Dokumente in Paltrows Lager gefunden? Vielleicht an seiner verwesenden Leiche? Jeder Hinweis auf die Angriffsmuster der Allianz wäre bei der Schlacht ums Steinkrallengebirge von Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger im Wyrmruhtempel", description = "Mein alter Freund Krasus berichtet von grässlichen Vorkommnissen im Wyrmruhtempel in der Drachenöde. Sein Schreiben war kurz, doch es scheint, dass eine Art Angriff auf das Rubinsanktum unterhalb des Tempels stattgefunden hat.\n\nDringende Angelegenheiten hier in Dalaran halten mich davon ab, mich persönlich um die Sache zu kümmern, doch sind mir Berichte Eurer Heldentaten in der Zitadelle des Lichkönigs zu Ohren gekommen und Ihr seid zweifellos dieser Aufgabe gewachsen - vielleicht könntet Ihr an meiner statt Krasus behilflich sein?", sourceObjective = "Sprecht mit Krasus im Wyrmruhtempel in der Drachenöde.", completion = "Ich danke Euch, dass Ihr Rhonins Bitte gefolgt seid, tapferer Abenteurer.\n\nLasst mich Euch mitteilen, was uns über die jüngsten Geschehnisse bekannt ist. Jede Hilfe, die Ihr zu gewähren bereit seid, wird sehr geschätzt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Sanktum", description = "{race}, etwas Schreckliches ist im Rubinsanktum unterhalb des Tempels geschehen.\n\nDer Eingang zum Sanktum liegt in Ruinen und seine Wächter sind auf grausame Art und Weise erschlagen worden. Wir haben Kundschafter ausgesandt, um der Sache auf den Grund zu gehen, aber sie sind nicht zurückgekommen. Nun befürchte ich das Schlimmste.\n\nBetretet das Rubinsanktum und bringt in Erfahrung, was in der Heimat meines Schwarmes passiert ist. Sobald wir mehr Informationen haben, können wir unsere nächsten Schritte entsprechend planen.", sourceObjective = "Untersucht das Rubinsanktum unterhalb des Wyrmruhtempels.", completion = "Habt Dank, {class}, dafür, dass Ihr mich aus Baltharus' Klauen gerettet habt!\n\nAllerdings gibt es noch immer sehr viel zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[26014] = { id = 26014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied", description = "Stillgestanden, <Gefreiter/Gefreite> {name}! Wir chaben kleine Problem!\n\nWir chaben geschickt Humphrey und Oskar Grabungslied zur Tiefenlichtkluft im Njordwesten, aber sie sind nicht zurückgekommen. Sie sollten ausspähen Umgebung, aber wir chaben verloren jeden Kontakt zu ihnen.\n\nEure Aufgabe, <Gefreiter/Gefreite> {name}, ist zu finden unsere Genossen und, falls sie noch ljeben, sie zu mir zurückzubringen!", sourceObjective = "Meldet Euch bei Humphrey Grabungslied in der Tiefenlichtkluft in Vashj'ir.", completion = "Natürlich sind wir noch nicht zurück! Wir haben ganz schön viele Rückschläge einstecken müssen… nicht zuletzt das Ableben meines geliebten Bruders Oskar.\n\n<Humphrey schnieft laut.>\n\nEr hat den Halt verloren und ist einfach davongetrieben, der Arme! Er wollte ein paar Fische für den Kapitän fangen, stattdessen wurde er weggespült und von einem dieser... dieser riesigen Aale gefressen! Uääääh hä hä häh hääääh!", sourceObjectiveStatus = "unverified-source-field" }
quests[26015] = { id = 26015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phosphorajagd", description = "Oskars letzter Wunsch, bevor er im Rachen dieses Großaals verschwand, war, dem Käpt'n Nahrung zu bringen. Also werden wir ihm diesen Wunsch erfüllen.\n\nMein Bruder hatte einen genialen Plan. Er hat beobachtet, wie diese Murlocs mit phosphoreszierenden Antennen Fische aus dem Schilf locken. Daraufhin hat er einen Weg gefunden, ein eigenes Gerät zu bauen. Ihr braucht nur etwas, das leuchtet.\n\nTötet die Krebse und Barsche am Grund der Kluft. Sie selbst sind nicht essbar, aber ihr Phosphora ist weitaus wertvoller als ihr Fleisch.", sourceObjective = "Besorgt Euch 6 Tiefenlichtphosphora von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen genug Phosphora, um ein starkes Licht zu erschaffen. Ihr müsst heller leuchten, als diese Murlocs!", completion = "<Humphrey nimmt Euch das Phosphora ab und bringt es an einem ungewöhnlichen Gerät an.>\n\nSo. Wunderschön! Oskar wäre sehr stolz darauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26016] = { id = 26016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle aus dem Basislager", description = "Paltrow, errichtet einen Stützpunkt im Scherwindtal. Ein starker Bodenangriff ist lebenswichtig für unseren Feldzug! Wenn wir Krom'gar angreifen, werden Eure Männer für das Chaos und die Verwirrung sorgen, die unsere Gnomflugmaschinen brauchen, um nahe genug für einen Bombenangriff an die Orcfestung zu kommen.\n\nDie Flugmaschinen werden die Bombe von Krom'gar zünden, während sie noch in ihrer Basis steht und damit die gesamte Festung auslöschen.\n\nNach dem Lesen verbrennen.\n\n-Truppenkommandant Valen\n\nBasislager der Nordwachtexpedition", sourceObjective = "Bringt die Befehle des Stützpunkts zu Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26017] = { id = 26017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder", description = "Bringt dieses Gerät an Eurem Kopf an und schwimmt dann durch den Tang und die Korallen am Rand der Kluft. Es sollte dort haufenweise kleine Fische geben, die Eure neue Antenne ganz unwiderstehlich finden werden.\n\nWenn wir zur Dämmerbucht zurückkehren, werden wir Berge von Fischen für alle haben!", sourceObjective = "Setzt die Phosphorafedora auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Das habt Ihr gut gemacht, {name}! Das habt Ihr richtig gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26018] = { id = 26018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht aus für die Tiefenlichter", description = "Ach, stimmt! Ich sollte ja einen Bericht erstellen! Fast hätte ich es vergessen!\n\nSieht eigentlich nach größtenteils harmlosen Wildtieren aus hier… Bis auf diese verdammten Aale. Und ein paar Murlocs. Ich schätze, der Käpt'n wird sich wohl eher für die Murlocs interessieren.\n\nFordert ein paar von ihnen zum Kampf raus und schaut, was sie so drauf haben. Soweit ich weiß, jagen die großen im Tang nach Fischen und die kleinen praktizieren irgendeine Art von Magie oder so... aber mehr weiß ich auch nicht.", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "<Humphrey hört Euch zu, während Ihr von Euren Kämpfen mit den Tiefenlichtmurlocs berichtet.>\n\nHmm… Klingt nach stinknormalen Murlocs… nur unter Wasser. Das macht den Käpt'n bestimmt froh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26019] = { id = 26019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormes Aalei", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Humphrey vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Humphrey Grabungslied am Grund der Tiefenlichtkluft in Vashj'ir.", progress = "Was habt Ihr denn da, {name}?", completion = "Waaa… ein Ei? Ein AALEI?\n\n<Sogar kopfüber könnt Ihr sehen, wie es in Humphreys Kopf rattert.>\n\nWir können ganz sicher etwas damit anfangen! Macht Euch bereit, denn jetzt ist es Zeit für ein wenig altmodische Rache à la Grabungslied!", sourceObjectiveStatus = "unverified-source-field" }
quests[26020] = { id = 26020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Bombgutz", description = "Wir müssen uns auf den bevorstehenden Angriff vorbereiten. Unsere Soldaten sollen die Bombe für den Transport bereitmachen. Ihr meldet Euch bei Obersprengenieurin Bombgutz. Sie versucht, unsere Luftabwehrkanonen zu reparieren, bislang jedoch erfolglos. Stellt sicher, dass ihre Motivation für die Reparatur der Kanonen ausreicht, {name}.", sourceObjective = "Meldet Euch bei Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", completion = "Ausreichend motiviert? Was... was soll das heißen? Hört mal zu, Unteroffizier, ich habe einen eingebauten Überlebensmechanismus namens Eigeninteresse. Das heißt, es ist in meinem eigenen Interesse, NICHT ZU STERBEN. Allerdings kann ich die Kanonen nicht ohne die richtigen Materialien reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26021] = { id = 26021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Grabungslied Teil 2: Der Eier-Aal-Trick-Blues", description = "Diese Aale haben meinen Bruder gefressen. Meinen Bruder, {name}! Es ist Zeit, dass ihnen jemand zeigt, wer hier der Boss ist.\n\n<Humphrey nimmt mehrere Dynamitstangen aus seiner Weste und schiebt sie durch die Außenhaut des Eis.>\n\nDiese Großaale im Süden sind zu stark, um alleine gegen sie anzutreten, aber mit diesem Ei sollten wir für Chancengleichheit sorgen können. Legt es in der Nähe dieser Biester ab und dann... Kabumm!\n\nWenn die Bombe den Aal nicht sofort tötet, sollte er zumindest dem Tod nahe sein, sodass Ihr ihm leicht ein Ende setzen könnt.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "Oskar ist am Leben? Wartet... Was habt Ihr gesagt? Ihr habt zugelassen, dass er ERNEUT DAVONGETRIEBEN WIRD?!\n\nNun… Ihr habt Euren Teil der Vereinbarung erfüllt und ich weiß zu schätzen, was Ihr getan habt, {name}.\n\nHier… nehmt das. Für mich ist es ohnehin nur Ballast, aber es scheint nicht viel zu nützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26022] = { id = 26022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Blut", description = "Seid bereit, {name}. Ihr werdet für uns das erste Blut auf diesem Land vergießen.\n\nDas Syndikat, so nennen sie sich, besteht aus feigen Menschen, die sogar ihr eigenes Volk verraten. Ihre Isolation macht sie zu einer leichten Beute.\n\nReist nach Norden, tötet alle Syndikatssöldner, die Ihr findet und erobert Nordhof im Namen der Verlassenen. Bringt mir die Blutsteinamulette, die sie tragen, als Zeichen Eurer Eroberung.", sourceObjective = "Erbeutet 10 Blutsteinamulette von Mitgliedern des Syndikats.", progress = "Ich lasse mich nicht von leeren Behauptungen beeindrucken. Könnt Ihr Eure Loyalität beweisen?", completion = "Das ist nur der Auftakt für das Massaker, das wir über dieses Land bringen werden. Alle werden Euren Namen kennen.\n\nDas habt Ihr gut gemacht, {name}. Sieg für Sylvanas!", sourceObjectiveStatus = "unverified-source-field" }
quests[26023] = { id = 26023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trollbann der Verlassenen", description = "Ich werde Euch eine Geschichte erzählen.\n\nEs gab einmal einen einfältigen Troll namens Zengu. Man befahl ihm, das Schwert Trol'kalar zu finden, die legendäre Klinge der menschlichen Trollbannlinie. Das gelang ihm. Er dachte, seine Aufgabe sei erfüllt und wollte Arathi allein verlassen. Dabei wurde er von den Menschen getötet, die das Schwert einfach wieder an sich nahmen.\n\nWir werden nicht so einfältig sein. Unsere Apotheker haben uns jemanden gebracht, der uns helfen wird, Trol'kalar wiederzubeschaffen: den Prinzen, der es einst besaß.\n\nEr wartet darauf, Euch zu führen, {name}. Sprecht mit ihm.", sourceObjective = "Sprecht mit Galen Trollbann.", completion = "Ja... Einst war ich Prinz des gefallenen Königreichs Stromgarde. Ich wurde getötet von dem, der Trol'kalar suchte.\n\nNun bereue ich mein dummes Leben. Ich diene...nur Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26024] = { id = 26024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Marez Schattenkutte", description = "Es wurde ein Kopfgeld auf Marez Schattenkutte ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Hauptmann Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie mit Dämonen Umgang hat. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", sourceObjective = "Bringt Marez' Kopf zu Hauptmann Nials bei der Zuflucht.", progress = "Seid gegrüßt, {class}. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Schattenkutte erledigt? Gut gemacht, {name}. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26025] = { id = 26025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verräterische Orc", description = "Ich bin mir sicher, dass eine mächtige Hexenmeisterin in den Mauern von Burg Stromgarde haust. Von Zeit zu Zeit beschwört diese Hexenmeisterin mit Hilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Anzahl. Wir müssen die Quelle ihrer Energie entfernen.\n\nFindet und tötet die Hexenmeisterin. Bringt mir das magische Objekt, das sie bei sich trägt. Dann werde ich dafür sorgen, dass es zerstört wird und dass ihre Macht nie wieder unser Land besudelt.", sourceObjective = "Erbeutet Marez Schattenkuttes beschmutzte Blutsteinkugel.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Die Hexenmeisterin muss aufgehalten werden.", completion = "Meine ruhelosen Nächte werden sich in friedlichen Schlaf verwandeln, wenn ich diese Kugel zerstört habe. Danke, {name}. Sie dient als düstere Erinnerung an die schreckliche Macht, die Dämonen über die Orcs ausübten, bevor Höllschrei sie von ihrem Fluch befreite.", sourceObjectiveStatus = "unverified-source-field" }
quests[26026] = { id = 26026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traum von einer besseren Zukunft", description = "Herr Rosie ist krank, <ehrenwerter/ehrenwerte:r> {race}. Könnt Ihr ihm helfen? Ihr müsst nur seinen Hut und seine Batterien finden, dann wird es ihm wieder gut gehen. Ich würde sie selbst holen, aber ich kann Herrn Rosie nicht allein lassen!\n\nDie gemeinen Kerle der Venture Company, hinten am Wasserrad, haben seinen Hut gestohlen und seine Batterien sind irgendwo an der Scherwindklippe versteckt. Ihr werdet richtig gut nach ihnen suchen müssen!\n\nWürdet Ihr bitte Herrn Rosies Besitz zurückbringen, damit er den Fieslingen von der Allianz eine Lektion erteilen kann?", sourceObjective = "Bergt die BD-816 Kriegsmaschine, das mechanisierte Feuer, das mechanisierte Eis und die mechanisierte Luft.", progress = "Herr Rosie ist so traurig. Wir müssen ihn wieder fröhlich machen!", completion = "<Clarissa klatscht aufgeregt.>\n\nHerr Rosie, dir geht es gleich wieder gut! Hurra!\n\n<Clarissa setzt die Teile, die Ihr gefunden habt, routiniert in \"Rosie\" ein.>\n\nOh, Herr Rosie! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[26027] = { id = 26027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", description = "Unser nächster Schlag gegen die Oger wird Euch tiefer in den Osten nach Burg Stromgarde führen. Die Lebenden klammern sich weiter an diese verfallenen Ruinen. Ihre Sentimentalität ist widerwärtig!\n\nFür uns ist Burg Stromgarde nicht mehr als ein verdorbener Bau voller Oger, die auf ihr Ende warten. Reist dorthin. Tötet ihre Schamanen und ihre Lords und sorgt dafür, dass das, was bei den Ogern als Führung durchgeht, vernichtet wird.", sourceObjective = "Tötet 7 Schamanen der Felsfäuste und 3 Lords der Felsfäuste in Stromgarde.", completion = "Alles gesäubert? Gut. Wir werden uns nicht die Mühe machen, Burg Stromgarde zu besetzen. Dieses Drecksloch muss in Staub verwandelt werden.\n\nDas Land würde sich gut für eine neue Unterstadt eignen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26028] = { id = 26028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr Rosies wilder Ritt", description = "Herr Rosie braucht jetzt einen Engel, der ihm bei der Navigation hilft. Werdet Ihr dieser Engel sein, <ehrenwerter/ehrenwerte:r> {race}? Mit Eurer Hilfe können wir es bis zur Klippe schaffen und viele, viele Allianzkämpfer töten. Was meint Ihr? Och bitte, <edler/edle:c> {class}! BITTE BITTE BITTE BITTE?\n\nWenn wir genügend Allianzler umbringen, kauft Herr Krom'gar uns allen ein Eis!", sourceObjective = "Tötet 20 Gnomingenieure und 5 Gnomklopfer.", completion = "<Oberanführer Krom'gar hustet.>\n\nIch weiß - vielleicht zum ersten Mal in meinem Leben - nicht, was ich sagen soll.\n\nIch bin mir nicht einmal sicher, wo Clarissa eigentlich her kommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26029] = { id = 26029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die echte Bedrohung", description = "Or'Kalar führt die Oger hier an. Seit Jahren entgeht er seinen Schlächtern. Seine Existenz ist eine Beleidigung der Dunklen Fürstin. Mug'thol, Verräter der Verlassenen, kommandiert ihn aus der Ferne!\n\nWir tolerieren weder Oger noch Verräter im Gebiet der Verlassenen. Bringt mir den Kopf des Ogers. Dann sorge ich dafür, dass er dieses Mal richtig verbrannt wird.", sourceObjective = "Tötet Or'Kalar und nehmt seinen Kopf.", progress = "Fasst Euch kurz.", completion = "Dieses Schicksal blüht allen, die uns im Weg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26030] = { id = 26030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Strom", description = "In grauer Vorzeit führte Lord Ignaeus von Strom, den sie Trollbann nannten, die erste menschliche Zivilisation von Arathor in den Krieg gegen die Trolle. Seine Klinge hieß Trol'kalar – was in ihrer alten Sprache Trolltöter heißt.\n\nIch war einer der letzten seines Geblüts und hatte die Aufgabe, Trol'kalar zu hüten... eine Aufgabe, bei der ich versagt habe. Aber jetzt werden wir die Klinge für meinen neuen Meister erneut in unseren Besitz bringen.\n\nDas Schwert wird von drei Siegelzeichen beschützt. Der erste befindet sich in den Händen der Verräter des Syndikats, die in den Ruinen von Stromgarde herumlungern. Tötet sie und bringt das Siegelzeichen zu mir.", sourceObjective = "Erhaltet das Siegelzeichen von Strom von den Mitgliedern des Syndikats in Burg Stromgarde.", progress = "Nur die Mitglieder des Syndikats innerhalb Stromgardes werden das Siegelzeichen bei sich haben. Außerhalb der Festung Blut zu vergießen ist Zeitverschwendung.", completion = "Ich habe das Syndikat zu Lebzeiten genauso sehr gehasst, wie ich sie im Tode hasse. Das Siegelzeichen wiederzusehen ist ein kleiner Trost.\n\nAber wir haben noch viel mehr Arbeit vor uns... für Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26031] = { id = 26031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen des Thoradin", description = "Als ich noch lebte, zerbrach ich das Siegelzeichen des Thoradin in fünf Teile, um es zu schützen. Ich gab sie meinen loyalsten Männern. Das schlug ebenfalls fehl, aber mein Nachfolger wird dasselbe getan haben.\n\nDie Verteidiger von Burg Stromgarde tragen die Teile des Siegelzeichens wieder bei sich. Tötet sie und bringt mir die Scherben; ich werde sie zusammensetzen.", sourceObjective = "Erbeutet 5 Siegelzeichenfragmente von Vollstreckern von Stromgarde in Burg Stromgarde.", progress = "Nur mit allen fünf Teilen kann das Siegelzeichen wiederhergestellt werden...", completion = "Thoradin war der Gründer von Arathor. Ich vereine diese Fragmente, so wie er einst die verstreuten Stämme der Menschen vereinte und ihre erste große Nation erschuf.\n\nDoch dieses Gefasel interessiert Euch sicherlich nicht. Vergebt mir. Alte Erinnerungen lassen sich nur schwer begraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26032] = { id = 26032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegelzeichen von Arathor", description = "Ich habe dieses Siegelzeichen Leutnant Heldenruf, dem Anführer meiner Kavallerie, anvertraut. Er hätte beinahe sein Leben verloren, als es gestohlen wurde.\n\nDieses Mal wird er wohl weniger Glück haben. Heldenruf patrouilliert zwischen Burg Stromgarde und der Zuflucht. Findet ihn und nehmt ihm noch einmal das Siegelzeichen ab.", sourceObjective = "Nehmt Leutnant Heldenruf das Siegelzeichen von Arathor ab.", progress = "Habt Ihr das Siegelzeichen?", completion = "Heldenruf war mir im Leben treu ergeben. Seinen Tod ertrage ich nur schwer.\n\nDoch das muss ich. Ich bin ein Verlassener. Meine alte Existenz hat keine Bedeutung.\n\nWir haben die Siegelzeichen; Trol'kalar erwartet uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26033] = { id = 26033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "Ich habe das letzte Siegelzeichen... und mit ihm vereine ich die vier zum Siegelzeichen von Trollbann, dem Schlüssel zur Gruft. Wir sind bereit.\n\nTrol'kalar wurde gemeinsam mit den Überresten seines Herrn eingeschlossen. Es liegt in Trollbanns Grabmal in den Katakomben von Burg Stromgarde. Es wird schwer bewacht sein... aber dass ich vor Euch stehe, beweist, dass die Vollstrecker besiegt werden können.\n\nBetretet das Grabmal, bergt Trol'kalar und bringt es her.", sourceObjective = "Bergt Trol'kalar aus Trollbanns Grabmal in Burg Stromgarde.", progress = "Habt Ihr Trol'kalar?", completion = "Trol'kalar, die Klinge meines Vaters... es erscheint mir, als hätte ich sie vor einer Ewigkeit zuletzt gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtzerstörer", description = "Dies war kein leichtfertiger Angriff, sondern vielmehr ein sorgsam inszenierter Schlag gegen das Herz des roten Drachenschwarms.\n\nZarithrian, der sich auf dem Felsvorsprung dort drüben befindet, überwacht den Angriff, doch ist der wahre Anführer ein dreister und mächtiger Zwielichtdrache namens Halion. Seit Dargonax ist kein ausgewachsenes Exemplar der Brut aus Sinestras verdorbenen Experimenten mehr gesichtet worden.\n\nTötet ihn, {name}. Sobald es Euch gelungen ist, diese Invasion zurückzudrängen, meldet Ihr Euch bei Krasus und berichtet ihm, was Ihr hier gesehen habt.", sourceObjective = "Besiegt Halion und drängt die Invasion des Rubinsanktums zurück.", progress = "Konnte die Situation im Rubinsanktum gelöst werden, {name}?", completion = "<Krasus hört konzentriert zu, während Ihr von Eurem Kampf gegen Halion berichtet. Seine Augen weiten sich, als Ihr Todesschwinge erwähnt.>\n\nWir schulden Euch großen Dank dafür, dass Ihr die Eindringlinge aus dem Sanktum getrieben habt. Doch die Neuigkeiten über den Zerstörer sind über alle Maße beunruhigend. Es gibt vieles, was ich mit den anderen Mitgliedern des Wyrmruhpakts besprechen muss.\n\nNehmt dies als Zeichen meiner Anerkennung, während Ihr Euch gegen den aufziehenden Sturm wappnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26035] = { id = 26035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Gewicht in Gold", description = "Erzmagier Malin hat mich hierher geschickt, um Reagenzien für ihn zu sammeln. Ich habe mich gefragt, wie ich ihm die Gegenstände besorgen soll, aber nun, da Ihr hier seid, könnte sich dieses Problem erledigt haben.\n\nIch benötige Hauer der Bleichborken und Medizinbeutel der Bleichborken.\n\nWürdet Ihr sie für mich holen? Die Bleichborken leben südöstlich von Arathi.", sourceObjective = "Erbeutet 10 Hauer der Bleichborken und 4 Medizinbeutel der Bleichborken von Trollen der Bleichborken.", progress = "Wie läuft es bislang?", completion = "Nicht schlecht. Da Ihr Euren Kopf anscheinend wirklich zum Denken benutzt, hoffe ich, dass Ihr uns in einer dringenderen Angelegenheit behilflich sein könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26036] = { id = 26036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab gegen Faust", description = "He, {name}. Tut mir leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandolübergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", sourceObjective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", progress = "Unser Ziel ist der Zauberstab, {name}. Konzentriert Euch vorerst nur darauf.", completion = "Genial, {name}. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26037] = { id = 26037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelanes Verteidigung", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen Euch gegen die Verteidigungsanlagen des Turms einsetzen. Dazu brauchen wir ein paar Edelsteine, an denen der Schamane der Felsfäuste Gefallen gefunden hat. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann.", sourceObjective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten in Burg Stromgarde.", progress = "Da seid Ihr ja wieder, {name}. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, {name}. Nochmals, gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber zu wirken, dann ist alles bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26038] = { id = 26038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm", description = "Hier ist das, wonach Ihr suchen müsst: Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat.\n\nAlle drei liegen in Kisten innerhalb des Turms. Die Kisten solltet Ihr allein problemlos öffnen können, passt nur auf die Oger auf.\n\nHaltet Eure Waffen bereit. Wenn die Oger herausfinden, dass Ihr dort seid und sie bestehlen wollt, dann werden sie nicht zimperlich mit Euch umgehen.\n\nSeid vorsichtig und viel Glück.", sourceObjective = "Findet Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt sie Skuerto in der Zuflucht.", progress = "Wenn Euch das gelingt, wird Malin sehr zufrieden mit Euch sein.", completion = "Malin hat genau die richtige Person um Hilfe gebeten, {name}. Das war tolle Arbeit!\n\nEs wird ihn freuen, dass unsere Mission ein so großartiger Erfolg war.", sourceObjectiveStatus = "unverified-source-field" }
quests[26039] = { id = 26039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Prinzessin", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, {name}, helft mir!", sourceObjective = "Sammelt 12 Körner von Myzrael von Kobolden der Trockenstoppel.", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26040] = { id = 26040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {race}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26041] = { id = 26041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", sourceObjective = "Holt den brennenden Schlüssel, den schäumenden Schlüssel und den donnernden Schlüssel vom Stein der Westlichen Bindung, dem Stein der Östlichen Bindung und dem Stein der Äußeren Bindung.", progress = "Dies ist der Stein der Inneren Bindung. Er ist der stärkste der Bindungssteine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "<Myzrael spricht durch den Stein.>\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger {class}, {name}. Mein Retter!", sourceObjectiveStatus = "unverified-source-field" }
quests[26042] = { id = 26042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hauptstein zerbrechen", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n{name}, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", sourceObjective = "Beschafft die Rute der Ordnung von Fozruk.", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", sourceObjectiveStatus = "unverified-source-field" }
quests[26043] = { id = 26043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl von Oberanführer Krom'gar ist das Betreten des Felskesselsees VERBOTEN!\n\nDie wilde Bestie, die Felskiefer genannt wird, hat den See in eine Todesfalle verwandelt. Solltet Ihr Felskiefer beseitigen, nehmt seinen riesigen Zahn als Trophäe und bringt ihn zur Herrin der Spione Anara. Sie wird Euch belohnen.", sourceObjective = "Tötet Felskiefer und nehmt Euch Felskiefers riesigen Zahn.", progress = "Was wünscht Ihr?", completion = "Ein Beweis für die Macht der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26044] = { id = 26044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Teile?", description = "Ich warte seit Tagen auf Teile für diese Waffen! Ich habe einen meiner besten Sprengenieure und zwei Dutzend Minenarbeiter vor fünf Tagen in die Ausufernden Tiefen geschickt, um die Teile zu besorgen. Als ich drei Tage später noch nichts von ihnen gehört hatte, begann ich mir Sorgen zu machen. Der Oberanführer schickte zwei seiner besten Orcs hinterher. Seitdem haben wir nichts gehört...\n\nBegebt Euch in die Ausufernden Tiefen, unmittelbar unter dieser Festung, und findet heraus, was los ist! Ich brauche die Teile!", sourceObjective = "Sprecht mit Unteroffizier Dontrag in den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Äh... Na ja, das ist ganz einfach... IN DIESER HÖHLE WIMMELT ES VON SEELENLOSEN MORDMASCHINEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[26045] = { id = 26045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Teile sind schon hier...", description = "Mein Dilemma sieht so aus: Ich habe zwei Möglichkeiten. Entweder lasse ich mich wie alle anderen hier unten umbringen oder ich werde in der Feste Krom'gar umgebracht, wenn Krom'gar erfährt, dass wir die Mine verloren haben. Ich wähle die dritte Möglichkeit: nichts tun. Klappt bisher ganz gut.\n\nIhr braucht Teile? In der Mine liegt eine Menge Schrott herum. Ihr müsst ihn nur holen.\n\nViel Glück! Wenn Ihr diese Teile holt, können wir uns vielleicht wieder in der Feste Krom'gar blicken lassen.", sourceObjective = "Sammelt 10 Ersatzteile.", progress = "Wie läuft die Jagd?", completion = "Ich fasse es nicht! Ihr habt die Teile bekommen und seid nicht gestorben. Wieso seid Ihr nur Unteroffizier?", sourceObjectiveStatus = "unverified-source-field" }
quests[26046] = { id = 26046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was immer wir tun...", description = "Dontrag kann das besser erklären als ich. Was auch immer wir tun, es ist das Falsche. Wir können hier unten nichts tun wegen all der Dinge, die uns umbringen wollen und können nicht zur Basis zurückkehren wegen all der Dinge, die uns umbringen wollen - verstanden?\n\nVielleicht können wir dieses Problem ja gemeinsam lösen. Beseitigt Ihr doch schon mal ein paar dieser Elementare, die anscheinend alles in der Mine umgebracht haben, einverstanden?", sourceObjective = "Tötet 12 tobende Erdelementare.", completion = "Holt die Teile, tötet die Elementare und rettet die Peons... Wenn wir das hinkriegen, ist uns eine Beförderung sicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[26047] = { id = 26047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deshalb nennt man sie Peons...", description = "Die beiden sind NUTZLOS! Als sie eintrafen, dachte ich, wir wären gerettet. Aber nein! Stattdessen warfen Dontrag und Utvoch einen Blick in die Mine und dachten sich einen idiotischen Plan aus, der vor allem aus Herumstehen besteht... wahrscheinlich, bis wir alle tot sind. \n\nIhr seht nicht ganz so nutzlos aus. Wollt Ihr uns helfen, <Freund/Freundin>? In den Ausufernden Tiefen verstecken sich Dutzende von Peons, die nur noch Angst in der Birne haben. Findet sie und holt sie raus!", sourceObjective = "Rettet 10 verängstigte Peons.", completion = "Ich wusste es! Ihr seid ein Held! Wenn ich etwas zu sagen hätte, würdet Ihr zum Legionär befördert!", sourceObjectiveStatus = "unverified-source-field" }
quests[26048] = { id = 26048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile hier herauf!", description = "Puh, das war hart. Ich dachte, wir würden es nicht schaffen, {name}. Am besten bringen wir diese Teile zurück zu Obersprengenieurin Bombgutz. Ich glaube, ich höre draußen schon das Summen der Gnomflugmaschinen. Wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt die Kiste mit Ersatzteilen zu Obersprengenieurin Bombgutz in der Feste Krom'gar im Steinkrallengebirge.", progress = "Habt Ihr meine Teile?", completion = "Gerade noch rechtzeitig! Die Flugmaschinen sammeln sich bereits. Der Angriff steht unmittelbar bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[26049] = { id = 26049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entfesselte Prinzessin", description = "Myzrael ist keine unschuldige Prinzessin. Sie ist unglaublich gefährlich. Die Riesen hatten sie aus gutem Grund dort unten angekettet. Man hat Euch leider betrogen.\n\nGerrig sagt, dass Ihr sie bei den Splittern von Myzrael, dort, wo Ihr zuerst mit ihr gesprochen habt, beschwören müsst. Besiegt sie und nehmt Euch ihre geisterhaften Fesseln. Bindet sie damit an die Splitter.\n\nIhr werdet diese Schriftrolle brauchen. Geht sorgsam mit ihr um; ich habe ein paar Zähne riskiert, um sie zu bekommen. Viel Glück, {name}.", sourceObjective = "Beschwört und besiegt Myzrael an den Splittern von Myzrael.", progress = "Die Splitter von Myzrael sind nun seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[26050] = { id = 26050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtbrille", description = "Als frisch gebackene Schwarzmeerräuber ist es unsere Aufgabe, dem ehrenwerten O'Breen bei der Suche nach dem verlorenen Elfenschatz zu helfen.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfsmittel im dunklen Wasser zu finden. Der Doktor hat für diesen Fall eine Brille konstruiert. Die Brille muss mit der Energie aus dem verzauberten Stein in der Höhle auf dem Hügel aufgeladen werden.\n\nDoch die Höhle ist verflucht! Man wird uns angreifen, wenn wir näher kommen. Verteidigt mich, dann kann ich die Energie aus dem Stein in die Brille übertragen.", sourceObjective = "Begleitet Professor Prasseltrop zur Höhle und zurück.", progress = "Keine Zeit für Gespräche! Die Brille muss mit der Macht des Steins aufgeladen werden!", completion = "Die Brille funktioniert nun perfekt! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26051] = { id = 26051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, {name}, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", sourceObjective = "Doktor Drechselknacks in der Faldirbucht will, dass Ihr 10 Elfenedelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, {name}. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26052] = { id = 26052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Wank", description = "Lassen wir Kapitän O'Breen nicht warten. Er wird die Edelsteine selbst sehen wollen. Deshalb sind wir schließlich hier!\n\nUnd nach ein paar Wochen in der Gesellschaft dieser Piraten haben der Professor und ich erkannt, dass es äußerst gesundheitsschädlich ist, sich mit ihren Schätzen erwischen zu lassen.\n\nHier, {name}, bringt sie zu O'Breen.", sourceObjective = "Bringt die Elfenedelsteine zu Kapitän O'Breen in der Faldirbucht im Arathihochland.", progress = "Ahoi, {class}. Was führt Euch auf die Brücke?", completion = "Dann haben sich die kleinen Gnome tatsächlich als nützlich erwiesen? Ich wusste doch, dass wir die Fersenbeißer nicht grundlos mitschleppen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26053] = { id = 26053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Hochlands", description = "Wir werden keine Bedrohung übersehen. Um dieses Land zu sichern und der Dunklen Fürstin zu unterwerfen, müssen wir alles, was auf ihm lebt, herausreißen, Stück für Stück, Meter für Meter.\n\nIm Nordosten, weniger als einen Steinwurf von diesem Lager entfernt, befindet sich ein Ogerhügel. Die Oger der Felsfäuste, die dort leben, müssen ausgelöscht werden, {class}.\n\nSie stehen uns im Weg. Zögert nicht und seid nicht gnädig.", sourceObjective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste.", completion = "Hervorragend. Der Marsch der Verlassenen geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[26054] = { id = 26054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser haben die vor?", description = "Die Sandwütertrolle und der Schattenhammer stecken unter einer Decke?!\n\nGanz gleich. Diese schändliche Hexe wird ihr Monster nicht über MEINE Stadt herfallen lassen.\n\nAuf, ihr Mutigen! Wir werden den Sand mit ihrem Blut tränken und siegreich nach Hause zurückkehren. Berichtet General Marcus Jonathan von den Vorfällen hier, wenn wir zurückgekehrt sind. Ich muss mich um die Rückkehr der Bürgerschaft, Reparaturen und dergleichen kümmern.", sourceObjective = "Tötet Kai'ju Gahz'rilla und informiert General Marcus Jonathan in Sturmwind darüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[26055] = { id = 26055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertrunkene Trauer", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", sourceObjective = "Kapitän Stahlmagen in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberinnen der Säbelflossen tötet.", progress = "Bah, vielleicht sollte ich diesen Nagaabschaum selbst umbringen. Es ist ja offensichtlich, dass Ihr es nicht tun werdet.\n\nVielleicht kann ich Euch ein paar Stricknadeln besorgen, damit Ihr Euch ein wenig beschäftigen könnt.", completion = "Ihr habt da draußen gute Arbeit geleistet, {name}.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26056] = { id = 26056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26057] = { id = 26057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wellensprecherin", description = "Ein Mitglied des Irdenen Rings, Wellensprecherin Valoren, ist in die Alptraumtiefen im Nordosten hinab geschwommen. Wir haben schon eine ganze Weile nichts mehr von ihr gehört.\n\nSchwimmt dorthin und schaut, ob Ihr sie finden könnt.", sourceObjective = "Findet Wellensprecherin Valoren in den Alptraumtiefen in Vashj'ir.", completion = "Bin ich froh, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[26058] = { id = 26058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Feste Krom'gar", description = "Wir haben keine Zeit mehr. Sie kommen! Übernehmt die Kontrolle über eine schwere Kanone und holt die Gnome vom Himmel! Die Bombe wird explodieren, wenn sie zu oft getroffen wird, und wir mit ihr!\n\nVerteidigt die Basis, {name}! Ihr seid unsere einzige Hoffnung!\n\nMeldet Euch bei Oberanführer Krom'gar, sollten wir das wider Erwarten überleben.", sourceObjective = "Zerstört 15 gnomische Flugmaschinen oder Gnomenbomber und 25 Gnomenschwadronskommandanten.", completion = "Ich habe noch nie eine so mutige Tat gesehen. Ihr habt die Basis gerettet, Unteroffizier - oder sollte ich besser Legionär sagen! Lok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26059] = { id = 26059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen und Ohren: Malaka'jin", description = "Ehrenwacht ist gefallen. Der Griff, in dem die Horde das Brachland hielt, wurde aufgesprengt, ebenso wie das Land. Nun erhalte ich Berichte, in denen es heißt, ein gemeinsamer Angriff der Allianz und der Grimmtotems würde Malaka'jin bedrohen. Wenn Malaka'jin fällt, fällt auch das halbe Steinkrallengebirge!\n\nIhr habt Euch als <fähiger Soldat/fähige Soldatin> der Horde erwiesen. Wollt Ihr meine Augen und Ohren in Malaka'jin sein? Hexendoktor Jin'Zil erwartet Euch.\n\nMalaka'jin befindet sich weit im Süden.", sourceObjective = "Meldet Euch bei Hexendoktor Jin'Zil in Malaka'jin im Steinkrallengebirge.", completion = "Wie ich sehe, schickt Krom'gar den Besten!\n\nGut, wir haben viel zu tun. Die dreckige Allianz hat ein Abkommen mit den Grimmtotems unterzeichnet. Jetzt müssen wir die Angriffe beider Streitkräfte abwehren.\n\nWir haben nicht genügend Soldaten im Hochwipfeltal und können es nicht mehr lange gegen die konzentrierten Angriffe unserer Feinde verteidigen. Wir haben nur noch eine Hoffnung: VOODOO!", sourceObjectiveStatus = "unverified-source-field" }
quests[26060] = { id = 26060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Stürmerherz", description = "Mit Voodoo könnte es unseren Truppen gelingen, den Angriff der Grimmtotems zurückzuschlagen. Allerdings brauche ich verschiedene Zutaten, um diese schwarze Magie zu wirken.\n\nDie erste Zutat auf meiner Liste ist das Herz eines Klippenstürmers. Die Bestien sind fast ausgerottet, aber in dieser Gegend gibt es noch ein paar. Findet eine und erbeutet ihr klopfendes Herz!", sourceObjective = "Besorgt ein Klippenstürmerherz.", progress = "Ich brauche das Klippenstürmerherz.", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26061] = { id = 26061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Widderhörner", description = "Um den Voodoo zu wirken, brauche ich besondere Reagenzien. Bringt mir Hörner der Steinkrallenwidder in dieser Gegend, {name}! Ohne die Hörner sind wir erledigt!", sourceObjective = "Besorgt 6 Hörner eines Steinkrallenwidders.", progress = "Ich brauche Hörner von Steinkrallenwiddern!", completion = "Hervorragend. Sobald ich die Zutaten habe, werde ich sie vermischen und den Voodoo entfesseln! Gnade unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26062] = { id = 26062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Voodoo: Resonitkristall", description = "Die letzte Zutat für das Voodooritual ist eine spezielle Kristallart namens Resonit. Man findet sie nur in den Steinschlaghöhlen westlich von hier. Passt auf die Kobolde auf! Sie beschützen das Resonit mit ihrem Leben!", sourceObjective = "Besorgt 8 Resonitkristalle.", progress = "Ich brauche die Resonitkristalle!", completion = "Endlich! Nun kann ich das Amulett mit der Voodooverzauberung erschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26063] = { id = 26063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin und ihr Hofstaat", description = "<Scholli grunzt.>\n\nHrmph.\n\nDinge brechen auseinander. Scholli unglücklich. Jetzt Schollis Gefährtin umgebracht von Spinnen in Weberkuhle. Scholli will Rache!\n\nHelft Scholli? Tötet Königin Silith und ihre kleinen Spinnlinge? Für Scholli? Für Schollis Gefährtin!\n\nWeberpass ist im Nordwesten, den Weg hoch. Geht!", sourceObjective = "Tötet Königin Silith und 10 beliebige Spinnen in der Weberkuhle.", completion = "Scholli immer noch nicht sehr glücklich, aber Scholli wird Euch für Tat belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26064] = { id = 26064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Kampf auf leeren Magen", description = "Die Truppen sind hungrig, {name}. Seit unsere Nachschublinien abgeschnitten wurden, gehen uns die Vorräte aus. Ich kann den Soldaten ein Festmahl zubereiten, wenn Ihr mir einige Zutaten besorgt.\n\nBegebt Euch in die Wälder westlich von hier und sucht nach Nestern der Kalimdoradler. Stehlt die Eier aus den Nestern und bringt sie mir.", sourceObjective = "Beschafft 8 Eier des Kalimdoradlers.", progress = "Ich brauche Eier!", completion = "Danke, {name}. Diese Eier reichen für eine Woche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26065] = { id = 26065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Willi", description = "Diese Tentakelschrecken haben das arme Tier eingefangen. Bitte, {name}, könnt Ihr es nicht retten, indem Ihr diese Abscheulichkeiten tötet?\n\nWürdet Ihr Willi seine Freiheit zurückgeben?\n\nHier, nehmt mein Totem und stellt es in der Nähe der Tentakel auf. Die Kälte, die es verströmt, bringt diese Monster zum Schrumpfen, sodass Ihr sie einfach besiegen könnt.", sourceObjective = "Tötet alle Tentakelschrecken, um Willi zu befreien.", completion = "Danke, {name}.\n\nDiese alptraumhaften Gestalten aus der Tiefe geben mir zu denken. Ich fürchte, dass unsere Anstrengungen vollkommen umsonst sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26066] = { id = 26066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung...", description = "Anscheinend haben wir fast keine großen, dummen Orcs mehr, die wir dem Feind entgegenschicken können. Das ist ein Problem. Zum Glück habe ich möglicherweise eine Lösung.\n\nNehmt diese Peitsche und geht nach Westen zur Steinschlaghöhle. In der Höhle werdet ihr ein schmutziges Koboldnest finden. Bändigt die Bestien mit meiner Peitsche. Wenn sie erst einmal gebändigt sind, werden sie tun, was wir wollen.\n\nKehrt zurück, wenn ihr eine anständig große Koboldarmee zusammen habt.", sourceObjective = "Bändigt 6 Steinschlagkobolde mit der Peitsche von Unterwerfer Devo.", completion = "In einer Krise wie dieser, könnte eine verzweifelte Tat uns den Sieg bringen. Vielleicht gewinnen wir, wenn wir einen Schwarm Kobolde auf den Feind hetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26067] = { id = 26067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zils Segen", description = "Ah, es ist vollbracht! Nun müssen wir ihn ausprobieren.\n\nReist zum größten Konfliktherd im Hochwipfeltal und setzt meinen Voodoostecken bei den Marodeuren von Krom'gar ein, die gegen die Grimmtotems kämpfen. Dank meiner Voodoomagie sollten sie ihre Schlagkraft zurückerhalten und unsere Feinde vernichten!\n\nGeht jetzt, {name}!", sourceObjective = "Benutzt Jin'Zil's Voodoostecken, um 12 Marodeure von Krom'gar mit Voodoo zu erfüllen.", completion = "Endlich ein Sieg! Allerdings wird er ohne eine stabile Nachschublinie nicht von langer Dauer sein. Genießt ihn so lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26068] = { id = 26068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut der Kobolde!", description = "Jetzt kommandieren wir die Koboldarmeen des Steinkrallengebirges! Klingt fast schon beeindruckend. Fast.\n\n<Devo seufzt.>\n\nDas Basislager der Allianz, nördlich von hier, wird streng bewacht. Es ist fast uneinnehmbar. Nur nordöstlich von hier, an der Grabstätte, gibt es einen Eingang. Nehmt das Koboldkriegshorn und brecht zur Grabstätte auf. Betretet sie von Osten, {name}! Von dort aus reist Ihr nach Westen, bis Ihr den Punkt erreicht, den ich auf Eurer Karte markiert habe. Benutzt das Horn und bringt die Wut der Kobolde über die Allianz!", sourceObjective = "Benutzt das Koboldkriegshorn nahe des Banners der Horde an der Grabstätte, um die Koboldarmee loszulassen!", completion = "<Devo lacht.>\n\nFaszinierende Geschichte, Freund. Unsere neuen Koboldverbündeten scheinen doch ganz nützlich zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26069] = { id = 26069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nura Pfadfinder", description = "Das Südliche Brachland wird von der Allianz angegriffen. Die Tauren bitten um Hilfe. Wir können sie nicht abweisen. Alle gesunden Soldaten der Horde sollten ihnen helfen.\n\nWenn Ihr sie unterstützen wollt, dann nehmt den Weg zum Höhenpfad. Ihr findet ihn im Dorf. Sucht nach Nura Pfadfinder.", sourceObjective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.", completion = "Die Lage ist ernst, {race}. Wir brauchen all die Hilfe, die wir kriegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26070] = { id = 26070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Unsere Freunde des Irdenen Rings hier haben uns gefragt, ob wir ihnen nicht zur Hand gehen könnten. Wie es scheint treiben im Brühgraben ein paar Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nKönnt Ihr Euch für mich darum kümmern?", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Das soll mir reichen. Hier ist Euer Anteil, wie versprochen.\n\nAber werdet nicht selbstgefällig, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26071] = { id = 26071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Diese Leute vom Irdenen Ring wollen, dass wir das Töten für sie übernehmen. Im Brühgraben treiben einige Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nSchwimmt mal runter und kümmert Euch darum.", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Gut gemacht.\n\nAber bildet Euch nicht zu viel darauf ein, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26072] = { id = 26072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Totem", description = "Ihr müsst mein Totem nach unten in den Brühgraben bringen. Benutzt es, um die Energien der Gesichtslosen einzufangen, wenn sie sterben. Das Totem wird sie davon abhalten, dahin zurückzukehren, wo sie herkamen.\n\nWenn das Totem ganz gefüllt ist, bringt es zu mir zurück. Wir werden es verwenden, um ihren Anführer aus der tiefsten Tiefe hervorzulocken.", sourceObjective = "Tötet 5 gesichtslose Entweiher, während sie sich in der Reichweite des Totems der Einsperrung befinden.", completion = "Ja, {race}. Könnt Ihr spüren, wie sie mit aller Macht versuchen auszubrechen und uns zu vernichten?\n\nDas ist gut! Sie sind der perfekte Köder für ihren Anführer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26073] = { id = 26073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Süden nichts Neues", description = "Kehrt jetzt zu Oberanführer Krom'gar zurück, {name}. Teilt ihm unsere Lage mit und berichtet, was Ihr getan habt, um Malaka'jin vor dem Fall zu bewahren.\n\nWir danken Euch für alles, was Ihr getan habt. Vielleicht werdet Ihr eines Tages Eure eigene Region kommandieren.", sourceObjective = "Meldet Euch bei Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "Lok'tar ogar! Ihr seid die Verkörperung all dessen, was einen Soldaten der Horde ausmacht, {name}. Hätten wir doch nur mehr wie Euch, dann wäre der Krieg bereits vorbei und Kalimdor würde der Horde gehören - UNANGEFOCHTEN!!\n\nErhebt Euch als ein Champion von Krom'gar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26074] = { id = 26074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anfang vom Ende", description = "Champion, wir haben ein neues Ziel anvisiert. Unsere Späher im Kriegsnarbental melden, dass die Nachtelfen an ihrer eigenen Massenvernichtungswaffe arbeiten und sie in einem uralten Baum verbergen. Sie werden nie die Gelegenheit bekommen, sie gegen uns einzusetzen.\n\nIhr werdet die Bombe zum Auftanken zu den Schlickwerken begleiten und danach zum Klippenläuferposten. Von dort aus werden wir die Bombe zünden und all unsere Feinde vernichten.\n\nGeht jetzt, {name}. Meldet Euch bei Jibbly Rakit, wenn ihr an den Schlickwerken eintrefft.", sourceObjective = "Fahrt im Heißluftballon von Krom'gar zu den Schlickwerken im Steinkrallengebirge.", completion = "Krom'gar hat seinen Champion geschickt! Ihr müsst Euch keine Sorgen machen, Champion. Wir tanken den Ballon rasch wieder auf. Wollt Ihr uns in der Zwischenzeit ein wenig helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26075] = { id = 26075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Probleme", description = "Wir haben ein kleines Problem...\n\n<Jibbly zeigt auf die großen Kothaufen, die überall in der Basis liegen.>\n\nWir haben die Schlickwerke in der Nähe eines Wyvernhabitats errichtet. Die Risszeichnungen der Schlickwerke wurden mit großer Sorgfalt erstellt, damit die Wyvernhabitate nicht gestört werden. Anscheinend verehren die Tauren und Orcs die Bestien. Wisst Ihr, was ich verehren würde? Einen Tag ohne Koteinschläge!\n\nGanz im Vertrauen, die Wyvern müssen sterben!", sourceObjective = "Tötet 6 beliebige Prachtschwingenwyvern.", completion = "Hoffentlich sind Euch keine entgangen. Ich halte das nicht mehr länger aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[26076] = { id = 26076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spionageplage", description = "Wir haben noch ein Problem, {name}. Es wimmelt hier von Allianzspionen! Ihr habt keine gesehen? Weil sie unsichtbar sind! Getarnt! Ich habe eine Lösung, aber dafür brauche ich jemanden, der die Kraft und das Geschick hat, meinen Plan umzusetzen.\n\nBenutzt diese Gasbombe, dann werdet Ihr die getarnten Spione sehen können. Schickt sie zu ihrem Schöpfer, wenn Ihr sie enttarnt habt.\n\nIhr erkennt einen getarnten Spion an dem Effekt, den sie auf die Luft haben. Seht genau hin!", sourceObjective = "Tötet 8 Allianzspione. Enttarnt die Spione mit Jibblys Gasbombe!", completion = "Alle dachten, ich spinne. Aber ich wusste, dass es hier überall Spione gibt. Und Kacke.", sourceObjectiveStatus = "unverified-source-field" }
quests[26077] = { id = 26077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Lieferung", description = "Oberanführer Krom'gar hat einen Befehl aus der Basis übermittelt. Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten. Der Plan sieht vor, von dort aus mit der Bombe die Allianz im Kriegsnarbental zu vernichten.\n\nMacht Euch auf, {name}. Man sollte Krom'gar nicht warten lassen.\n\nSprecht mit General Grebo, wenn Ihr Euer Ziel erreicht habt. Er wird Euch über Eure nächste Mission informieren.", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten im Steinkrallengebirge.", completion = "Häuptling Klippenläufer und seine Tauren wollen die Horde verraten! Sie behaupten, dass der uralte Baum im Kriegsnarbental nur eine Druidenschule ist. Sie verstehen nicht, dass Kriegszeiten verzweifelte Maßnahmen verlangen. Meine Späher haben mir versichert, dass die Nachtelfen eine äußerst mächtige Waffe in diesem Baum verbergen. Wir müssen damit aufräumen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26078] = { id = 26078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht die Feuer", description = "Der Angriff der Dunkeleisenzwerge hat uns überrascht. Ihre Saboteure haben viele unserer Flugzeuge, Dampfpanzer und Vorräte beschädigt. Wir konnten nur noch ein paar Bomber rechtzeitig starten.\n\nJeder Techniker, jeder Rekrut und jede Wache, die ich entbehren kann, versucht verzweifelt, die anderen zu reparieren und startklar zu machen. Unsere Infanterie kann nicht mehr lange ausharren. Nehmt diese Ausrüstung und helft bei der Löschung der brennenden Bomber.", sourceObjective = "Löscht 6 Feuer auf dem Flugplatz von Eisenschmiede mit Eurer Feuerwehrausrüstung.", progress = "Beeilung! Die Bomber müssen starten!", completion = "Gut gemacht! Meine Männer arbeiten hart daran, unsere Flugmaschinen und die Dampfpanzer kampfbereit zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26079] = { id = 26079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Falkenstein und Otto", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.", sourceObjective = "Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, {name}. Ich freue mich, sie auszuzahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26080] = { id = 26080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "{name}, Ihr müsst das hier zu Käpt'n Glovaal bringen. In meinem Zustand bräuchte ich sicher eine Woche, um zur Dämmerbucht zu gelangen. Aber wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt Grabungslieds Fisch und Tipps zu Kapitän Glovaal in der Dämmerbucht.", progress = "Chabt Ihr Oskar und Humphrey gefunden?", completion = "Ich verstehe. Ja, ich mich erinnere jetzt… Humphrey und Oskar waren nicht die besten Schwimmer.\n\nDie Informatjionen sind sehr chilfreich und der Fisch sieht sich sehr ljecker aus. Wenn Ihr Cherr Grabungslied seht, bevor er zurückkehrt, bitte sagt ihm danke von mjir.", sourceObjectiveStatus = "unverified-source-field" }
quests[26081] = { id = 26081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alinas Belohnung", description = "Hier endet also die Geschichte von Trol'kalar. Diese Waffe wird im Namen der Dunklen Fürstin den Lebenden den Tod bringen.\n\nVerlasst mich jetzt, {name}. Es obliegt mir erneut, die Klinge zu bewachen. Berichtet Alina von Eurem Sieg. Sie wird Euch sicherlich belohnen", sourceObjective = "Sprecht mit der Dunklen Waldläuferin Alina.", completion = "Die Nachricht von Eurem Sieg stimmt mich zufrieden, {class}... ein seltenes Gefühl. Die Dunkle Fürstin glaubt, unsere Eroberung von Lordaeron wäre vielleicht die einzige Möglichkeit, den Verlassenen wahre Zufriedenheit zu schenken, vielleicht sogar Erleichterung.\n\nDoch das spielt keine Rolle. Unser Sieg ist unausweichlich. Für Eure Loyalität im Dienste der Verlassenen belohne ich Euch im Namen von Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26082] = { id = 26082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Kriegsnarbe!", description = "Ich werde dem alten Narr erlauben, seinen Fall vorzutragen. Er behauptet, er könne Beweise dafür bringen, dass die Nachtelfen keine Massenvernichtungswaffe besitzen. Wir werden sehen.\n\nWährend wir auf diesen Beweis warten, werdet Ihr unsere Armee im Tal unterstützen. Zu diesem Zweck haben wir eine große Anzahl Belagerungspanzer vorbereitet. Unsere Verwüster sind angriffsbereit.\n\nNehmt den Fahrstuhl hinunter zum Boden des Außenpostens und übernehmt einen Verwüster von Krom'gar. Vernichtet damit unsere Feinde im Kriegsnarbental.", sourceObjective = "Benutzt den Verwüster von Krom'gar, um 5 darnassische Glevenschleudern und 20 beliebige Soldaten der Allianz im Kriegsnarbental zu vernichten.", progress = "Tötet sie alle!", completion = "Ihr beweist ein ziemliches Zerstörungstalent, {name}. Die Allianzsoldaten, die nach Eurer wilden Fahrt durch das Kriegsnarbental noch übrig sind, wird die Bombe erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26083] = { id = 26083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallo Lolo", description = "Gichtdarm war geschickt spähen. Guckt viele Dinge. Groß Abenteuer!\n\nGichtdarm findet geheim Piratschiff. Piraten viel Angst, laufen weg. Aber Oger Lolo nicht laufen. Lolo macht gut Freund mit Gichtdarm!\n\nGichtdarm muss weg, aber vermissen Lolo. Ihr sagen hallo zu Lolo von Gichtdarm.", sourceObjective = "Findet Lolo den Ausguck in der Faldirbucht.", completion = "Ihr Freund von Gichtdarm! Er komisch Oger. Riechen seltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[26084] = { id = 26084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "Ihr habt uns hier gut gedient, {name}. Wir haben ein Zeichen gesetzt, aber die nächste Phase unseres Eroberungsfeldzugs wird Monate brauchen, nicht nur Minuten.\n\nEs gibt noch viel zu tun. Ich werde Euch den langweiligen Teil - das Warten auf das Eintreffen der Wehrbefestigungen - ersparen. Reist gen Osten nach Hammerfall. Die Orcs dort werden Eure Hilfe gebrauchen können.", sourceObjective = "Meldet Euch bei Gor'mul in Hammerfall im Arathihochland.", completion = "Throm'ka, {class}. Wenn Eure Taten für die Untoten so bemerkenswert waren, wie Ihr sagt, fühle ich mich geehrt, Euch beim Dienst für die Horde zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26085] = { id = 26085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Verteidiger", description = "Während unsere Ingenieure dafür sorgen, dass die Bomber bald wieder fliegen, kämpfen unsere Wachen und Gebirgsjäger gegen die Eindringlinge.\n\nSeit Beginn des Einmarschs sind sie dort draußen, ohne Zeit für Schlaf oder Essen. Die Verteidiger von Eisenschmiede gehören zu den besten Azeroths, aber selbst sie haben Grenzen.\n\nNehmt diese Banner und platziert sie in Verwehungen aus losem Schnee. Erinnert die Soldaten an das, wofür sie kämpfen und stärkt ihre Moral.", sourceObjective = "Platziert 8 Eisenschmiedebanner in Hügeln aus losem Schnee überall auf dem Flugplatz von Eisenschmiede.", completion = "Die Soldaten entdecken verborgene Reserven der Stärke und des Mutes und werfen sich den Dunkeleisenzwergen entgegen. Solange wir hier sind, wird der Flugplatz nicht fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26086] = { id = 26086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orako", description = "<Kapitän Verne sieht auf seine Uhr.>\n\nWo ist dieser Jäger? Ich habe Orako vor einer Woche in die Tiefenlichtkluft geschickt, um einen Bericht zu schreiben! Ja, er ist schon ganz schön anstrengend und ich hätte nichts dagegen, ihn vom Hals zu haben, aber ich brauche seinen Bericht.\n\nIhr da! Wie heißt Ihr? {name}? Würdet Ihr ihn für mich ausfindig machen? Es scheint zwar merkwürdig, dass <ein/eine:c> {class} einen Jäger suchen soll, aber mir bleibt keine andere Wahl.", sourceObjective = "Meldet Euch bei Orako bei der Tiefenlichtkluft in Vashj'ir.", completion = "Gah! Diese Fische sind einfach nicht zu treffen!\n\n<Orako schaut Euch an.>\n\nMein Wolf wurde von einem Fisch gefressen und ich gehe nicht zurück, bis ich ihn gefunden habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26087] = { id = 26087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtsaft", description = "Es ist einfach, einen Fisch in einem Fass zu erschießen. Einen Fisch in einem Meer zu erschießen ist da schon schwieriger.\n\nHabt Ihr die Murlocs unten in der Kluft gesehen, {class}? Sie schießen überhaupt nicht! Sie tragen kleine Kugeln voller Leuchtsaft auf dem Kopf, dank derer die Fische zu IHNEN kommen. He, das sollten wir auch versuchen!\n\nGeht nach Süden und tötet die Krebse und Barsche in der Kluft. Sie haben haufenweise Leuchtsaft in ihrer Haut. Ich habe es genau gesehen!", sourceObjective = "Besorgt Euch 6 Einheiten Leuchtsaft von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen haufenweise Leuchtsaft!", completion = "Schaut nur, wie das leuchtet!\n\n<Orako blickt sehnsüchtig in die Ferne.>\n\nMein Wolf hat leuchtende Dinge geliebt…", sourceObjectiveStatus = "unverified-source-field" }
quests[26088] = { id = 26088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein!", description = "<Orako formt einen Ball aus dem Leuchtsaft und bringt ihn dann an einem Gerät an, an dem er offensichtlich schon lange bastelt.>\n\nHier, ich habe einen Hut für Euch. Er hat ein Licht, das Fische anlockt. Genau wie bei den Murlocs!\n\nDie Murlocs jagen gerne im Tang und in den Korallen an den Seiten der Kluft. Wenn Ihr diesen Hut aufsetzt und durch den Tang schwimmt, könnt Ihr vielleicht genauso Fische fangen, wie sie.", sourceObjective = "Setzt den Fischerhut auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Hm… Ihr habt ganz schön viele Fische, aber das sind nicht die, die meinen Wolf gefressen haben. Ich schätze, es war ein größerer Fisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26089] = { id = 26089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirb, Fischmann, stirb", description = "Ein Fisch hat meinen Wolf gefressen, und Murlocs sehen aus wie Fische. Diese Murlocs werden bezahlen!\n\nGeht zurück in die Kluft und tötet diese Fischmänner! Mein Wolf wird seine Rache bekommen!", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "Ich weiß, dass Murlocs keine Fische sind. Ich dachte nur, sie zu töten würde meine Laune heben. Aber ich bin immer noch traurig wegen meines Wolfs.\n\n<Orako seufzt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26090] = { id = 26090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier, ein Ei!", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Orako vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Orako bei der Tiefenlichtkluft in Vashj'ir.", progress = "<Bamm!>\n\nIhr habt mir etwas mitgebracht?", completion = "Das ist ein großes Ei.\n\n<Orako schnüffelt daran.>\n\nEs ist groß und es riecht nach Fisch. Vielleicht ist der große Fisch, von dem dieses Ei stammt, ja der, der meinen Wolf gefressen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[26091] = { id = 26091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein, Teil 2: Der Eier-Aal-Trick-Blues", description = "<Orako nimmt eine Sprengfalle aus seiner Tasche und schiebt sie durch die äußere Hülle des Eis.>\n\nJetzt wird das Ei explodieren. Legt es in der Nähe eines dieser gigantischen Aale ab und wartet, bis er näher kommt. Wenn das Ei explodiert, ist der große Fisch schon halbtot und Ihr könnt ihn leicht erledigen.\n\nRettet meinen Wolf! Mit diesem Ei wird es Euch gelingen.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "<Orako spielt ausgiebig mit Wolf.>\n\nOh, vielen Dank, {name}! Ich wusste, dass Wolf noch lebt!\n\nHier, bedient Euch. Ich habe dafür keine Verwendung mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26092] = { id = 26092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orakos Bericht", description = "<Ihr erinnert Orako daran, dass er einen Bericht an Kapitän Verne senden sollte.>\n\nStimmt, ein Bericht. Alles, was ich hier gesehen habe, sind Fische. Fische, Fische und nochmals Fische.\n\n<Orako wirft einen Blick auf den Sack Fische, den Ihr ihm mitgebracht habt.>\n\nBringt das zurück zum Kapitän. Das ist mein Bericht.", sourceObjective = "Bringt Orakos Bericht zu Kapitän \"Juwel\" Verne in der Schattenhöhle.", progress = "Wo war er? Was ist passiert?", completion = "Das ist sein Bericht?! Dieser Idiot…\n\nIch schätze, wir können die Nahrung gut gebrauchen. Danke, {name}. Ihr habt Eure Aufgabe so gut erledigt, wie ich es erwartet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26093] = { id = 26093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordhof", description = "Wir kämpfen in einem Krieg um Stromgarde und wir verlieren. Die Oger, das Syndikat und wir selbst haben unsere einst mächtige Stadt zerrissen und jede Fraktion kämpft mit der anderen bis zu einem blutigen Patt.\n\nAber unsere Truppen werden dezimiert, während die Zahl der Feinde ansteigt.\n\nAuch wenn Süderstade gefallen ist, dürfen wir unseren Feinden keinen Fußbreit unseres Bodens mehr überlassen.\n\nGeht zum Hauptquartier des Syndikats im Nordhof und tötet ihre Mitglieder. Wir müssen das Land für uns zurückerobern, bevor die Horde die Gelegenheit hat, sich weiter auszubreiten.", sourceObjective = "Tötet 10 Mitglieder des Syndikats beim Nordhof.", completion = "Sehr gut, {name}. Das Letzte, was wir bei der Bedrohung durch die Untoten noch brauchen, ist ein Angriff von einer Bande gewöhnlicher Diebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26094] = { id = 26094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Mein Chefingenieur sagt, dass er einen der Bomber repariert hat. Er ist startbereit. Nehmt diese Bomben und sucht den reparierten Bomber am Anfang der Rollbahn.\n\nSetzt die Bomben ein, sobald Ihr in der Luft seid, und richtet unter den angreifenden Dunkeleisenzwergen so viel Schaden wie möglich an. Ich habe Gerüchte gehört, laut derer sie eine neue Art von Kriegsgolem einsetzen wollen. Sucht nach diesen Golems. Sie sind Eure wichtigsten Ziele.", sourceObjective = "Steigt in den reparierten Bomber und tötet 30 Angreifer der Dunkeleisenzwerge mit der Eisenhammerbombe. Ihr könnt beliebige Dunkeleisenzwerge oder ihre Verbündeten auf dem Flugplatz töten.", completion = "Das Blatt wendet sich, {name}, größtenteils dank Eurer Leistungen. Jetzt müssen wir den Anführern der Dunkeleisenzwerge einen Schlag versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26095] = { id = 26095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen von Stromgarde", description = "Das Syndikat in Stromgarde kämpft dort gegen unsere Milizeinheiten. Um den Abschaum dazu anzustacheln, unsere disziplinierteren Truppen anzugreifen, hat das Syndikat ein Kopfgeld auf unsere Soldaten ausgesetzt. Sie belohnen jedes Abzeichen von Stromgarde, das einem toten Milizsoldaten abgenommen wird, mit Gold.\n\nWir wollen diese Abzeichen wieder haben. Diese Halsabschneider dürfen keine Trophäen unserer mutigen Gefallenen behalten!\n\nBetretet den vom Syndikat kontrollierten Teil von Burg Stromgarde und bringt unsere Abzeichen an Euch.", sourceObjective = "Erbeutet 7 Abzeichen von Stromgarde vom feindlichen Syndikat in Burg Stromgarde.", progress = "Konntet Ihr Abzeichen von Stromgarde erbeuten, {name}? Das Syndikat muss begreifen, dass es von unseren Toten nicht profitieren wird.", completion = "Danke, {name}. Wir werden den Familien dieser gefallenen Soldaten mitteilen, dass sie im Kampf getötet wurden.\n\nSelbst schlimme Nachrichten sind besser als im Ungewissen über das Schicksal eines Angehörigen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26096] = { id = 26096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrühende Pilze", description = "Wir glauben, dass wir eine gute Verwendung für die Gnadenlosen gefunden haben, die Euer Freund aus der Höhle uns gebracht hat. Ich benötige jedoch ein Konservierungsmittel dafür.\n\nUnten im Brühgraben findet Ihr Pilze, die genau die Eigenschaften haben, die ich brauche. Bringt mir ein paar davon und ich schaue, was ich tun kann.", sourceObjective = "Sammelt 5 Verbrühende Pilze.", progress = "Ich habe gehört, dass Ihr ein unangenehmes Erlebnis hattet, als Ihr Euch einen der Dämonen auf den Kopf gesetzt habt. Ich kann Euch jedoch versichern, dass sie jetzt alle mausetot sind.", completion = "Ich werde die Pilze als Reagenz benutzen, um die Kadaver einzubalsamieren. Wir haben gleich einen für Euch vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26097] = { id = 26097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis für eine Lüge", description = "Im Herzen des Kriegsnarbentals steht ein uralter Baum - ein Baum, der den Zeitaltern widerstanden hat und seit Generationen als ein Ort des Friedens und der Lehre genutzt wird. Solange ich denken kann, hat meine Familie in diesem Hain zusammen mit den Nachtelfen das Druidentum studiert. Und jetzt soll ich glauben, dass sich in diesem Baum eine Massenvernichtungswaffe der Allianz befindet?\n\nKrom'gar irrt sich. Das werde ich beweisen!\n\nIch habe meinen Sohn Orthus in den Hain von Thal'darah geschickt. Er soll nach der Waffe suchen. Geht dorthin und trefft ihn.", sourceObjective = "Findet Orthus im Hain von Thal'darah im Steinkrallengebirge.", completion = "Orthus ist tot. Er hält etwas in der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26098] = { id = 26098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat im Hain", description = "Der Raum ist voller toter Druiden. Etwas stimmt nicht, denn Ihr seht keine Anzeichen eines Kampfes. Von der Tür führen blutige Schleifspuren ins Innere.\n\nIhr öffnet Orthus' erstarrte Faust und findet etwas verstörendes: ein Insigne des Generals von Krom'gar.\n\nBringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer.", sourceObjective = "Bringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer am Klippenläuferposten im Steinkrallengebirge.", progress = "Er... Mein Kind ist tot?", completion = "<Ihr gebt Oberhäuptling Klippenläufer das Insigne.>\n\n<Oberhäuptling Klippenläufer schreit wütend auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26099] = { id = 26099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das soll Gerechtigkeit sein?", description = "Er war ein guter Junge, {name}. Jung, liebevoll. Niemals hätte er einen der jungen Druiden getötet. Sie waren seine Freunde! Nein... Nicht Orthus.\n\nDer General muss sich für dieses Verbrechen verantworten. Ich verlange Gerechtigkeit!", sourceObjective = "Verteidigt Euch.", progress = "Das ist gerecht.", completion = "Ihr habt es mit eigenen Augen gesehen, {name}. General Grebo hat uns angegriffen!\n\n\n\nWas sollen wir jetzt tun? Der Kriegshäuptling wird uns als Verräter hinrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26100] = { id = 26100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der General ist tot", description = "Würdet Ihr mit Oberanführer Krom'gar reden, {name}? Vielleicht hört er ja auf Euch. Ihr seid schließlich ein Champion in seiner Armee. Ihr habt alles gesehen. Bitte helft uns, {name}. Wir wollen doch nur in Frieden gelassen werden.\n\nSprecht mit Oberanführer Krom'gar und versucht ihm zu vermitteln, dass wir nicht wollten, was geschehen ist.", sourceObjective = "Sprecht mit Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "WAS? Die Tauren haben meinen General umgebracht? Das ist Verrat! HOCHVERRAT! Für diesen schweren Fehler werden sie bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26101] = { id = 26101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Gesetz", description = "Es war richtig, dass Ihr mir dieses Verbrechen gemeldet habt. Die Täter werden für dieses feige Verbrechen bezahlen. Blut wird fließen.\n\nOhne Grebo fehlt mir ein General. Ihr werdet seinen Platz einnehmen.\n\nTrefft mich am Klippenläuferposten, General. Zusammen werden wir diesen Schwachsinn beenden.", sourceObjective = "Trefft Oberanführer Krom'gar am Klippenläuferposten im Steinkrallengebirge.", completion = "Der verräterische Tauren wird zusehen, wie wir seinen geliebten Hain vernichten und sein Dorf niederbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26102] = { id = 26102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmaxts Ende", description = "Dank eures Einsatzes ist der Angriff der Dunkeleisenzwerge ins Stocken geraten. General Grimmaxt, der Anführer der Dunkeleisenzwerge, versucht, seine Truppen aus ihren Reihen auf dem gefrorenen See im Süden anzutreiben.\n\nEr steht auf einem ihrer neuen Dunkeleisengolems und ruft seinen Soldaten Befehle zu. Wenn es ihm gelingt, sie zu motivieren, überrennen sie uns vielleicht doch noch. Das müsst Ihr verhindern, {name}. Zerstört den Golem, der General Grimmaxt beschützt, dann ihn selbst. Er ist der Schlüssel zu unserem Sieg.", sourceObjective = "Tötet General Grimmaxt auf dem Flugplatz von Eisenschmiede.", completion = "Geschafft! Ohne Eure Hilfe hätte der Feind den Flugplatz von Eisenschmiede erobert. Dann hätten die Dunkeleisenzwerge freie Bahn bis Eisenschmiede gehabt.\n\nDer Rat der Drei Hämmer muss erfahren, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26103] = { id = 26103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biotreibstoff", description = "Unterseeboottreibstoff ist teuer!\n\nDie Machthaber in Gnomeregan waren so freundlich, uns mehrere Treibstofffässer zur Verfügung zu stellen, aber wir verbrauchen sie schneller als erwartet. Das bedeutet, dass wir improvisieren müssen.\n\nEs ist kein Geheimnis, dass die Meereslebewesen allerlei interessante Chemikalien enthalten... wie zum Beispiel Öl. Bringt dieses Gerät zu Korthuns Ende und benutzt es an Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Wenn wir nicht mehr Unterseeboottreibstoff beschaffen können, ist ihr Öl vielleicht unsere einzige Hoffnung.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Wie hat das Gerät funktioniert, {name}?", completion = "<Ingenieur Hexasept steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26104] = { id = 26104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt das Lasso raus", description = "Seid gegrüßt, <Genosse/Genossin>.\n\nEndlich ist eingetroffen Verstärkung und bringt Nahrung, Männer und neue Reittiere. Einzige Problem ist, dass unsere Reittiere unter Wasser nicht so gut vorankommen.\n\nDirekt über dieser Chöle findet Ihr chohe Säulen mit roten, blättrigen Tang obenauf. In dem Tang verstecken sich Seepferdchen. Werft dieses Lasso in den Tang und cholt uns ein paar Reittiere, die wir benutzen können chier unter Wasser.", sourceObjective = "Benutzt das Seepferdchenlasso in der Nähe des Tangs auf den Säulen in Korthuns Ende, um 5 panische Seepferdchen zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26105] = { id = 26105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Die Horde hat Spione in dieser Gegend? Die Dämmerbucht ist ganz in der Nähe und die Zange X2 befindet sich dort! Die Horde darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Dämmerbucht darüber informieren… nachdem Ihr mehr von diesen dreckigen Spionen der Horde den Garaus gemacht habt!", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Horde auf der Hut sein. Die Zange X2 hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26106] = { id = 26106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoffologie leicht gemacht", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Dämmerbucht, um den perfekten Biotreibstoff herzustellen.", completion = "Habt Ihr je daran gedacht, eine wissenschaftliche Karriere anzustreben, {name}? Wenn Ihr je genug von Eurem derzeitigen Metier habt, meldet Euch bei mir. Ich könnte einen Assistent mit Eurer Passion für Experimente und wissenschaftliche Arbeit brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26107] = { id = 26107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmungsaufheller", description = "Dank der Schamanenkünste unseres Volkes konnte ich Jahre der Lethargie hinter mir lassen. Jetzt sorge ich für alle hier und stelle den Segen her, der auch mir neue Kraft schenkte.\n\nDie Hochlandraptoren sind tückische und wilde Bestien. Ihre Geister können unseren Kriegern große Stärke geben. Bringt mir Raptoraugen, damit ich die Amulette herstellen kann, so wie es mich Tor'gan lehrte.", sourceObjective = "Erbeutet 10 Hochlandraptoraugen von Hochlandschreitern oder Hochlandhauern.", progress = "Die Wildheit in den Augen der Raptoren wird auf unsere {class} übergehen.", completion = "Die Lethargie, die mich nach dem Fall unserer Lager überkam, war so stark, dass ich das Geschenk ablehnte, als man es mir anfangs machte.\n\nNun bin ich stolz darauf, meinen Anteil im Namen der Horde zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26108] = { id = 26108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Die Hochlandfleischpirscher im Süden sind noch wilder als ihre Artgenossen. Sie besitzen nicht nur Stärke, sondern auch große List.\n\nAls ich in der Lethargie gefangen war, konnten mich selbst Amulette der Stärke nicht bewegen. Doch Tor'gan benutzte die Herzen der Fleischpirscher, um mich mit einem Geist zu erfüllen, der meine Zweifel besiegte und mich befreite.\n\nUnsere Soldaten verdienen die List des Raptors. Sammelt Fleischpirscherherzen für mich, {name}.", sourceObjective = "Sammelt 12 Raptorherzen von Hochlandfleischpirschern.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ich übertrage die Macht und den Geist der Raptoren in diese Kugel, so wie es mich Tor'gan gelehrt hat. Sie wird die {class} mit der wilden Stärke und der Intelligenz des Raptors erfüllen.\n\nDie List des Raptors erfüllt Euch nun auch, {class}. Nehmt sie mit Stolz an. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26109] = { id = 26109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land in Sicht!", description = "Lolo sieht was Winziges, es ist <ein/eine:r> {race}! Immerzu Ausschau halten, ja, ja, das tut Lolo!\n\nWillkommen in der Faldirbucht. Kapitän O'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Beutebucht zu segeln.\n\nAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme \"Silbergeist\" und die arme \"Tolle Minna\". Sie ruhen jetzt auf dem Grund des Meeres!\n\nLolo schlägt vor, dass Ihr mit Kapitän O'Breen sprecht, wenn Ihr länger hier bleiben wollt.", sourceObjective = "Sprecht mit Kapitän O'Breen in der Faldirbucht im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[26110] = { id = 26110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie in alten Zeiten", description = "Schon seltsam. Kin und ich haben so einiges zusammen durchgemacht und doch finden wir uns in Arathi wieder, wie schon vor so vielen Jahren.\n\nHier vereitelten wir einen Plan zur Schaffung einer neuen Seuche, sie und ich. Die Horde scheint ihre Lektion nicht gelernt zu haben, denn es wimmelt schon wieder von ihnen auf diesem Hof.\n\nIhr untoter Kurier schlurft für jeden sichtbar umher. Ihr könnt uns helfen. Findet den Kurier und bringt mit, was auch immer er bei sich trägt.", sourceObjective = "Nehmt der Kurierin der Verlassenen den versiegelten Ordner ab.", progress = "Vielen Dank für Eure Hilfe bei der Suche nach dem Kurier, {name}.\n\nWährend Eurer Abwesenheit sah Kin einen Apotheker, der aus dem gleichen Haus südlich von hier kam. Ich bin mir sicher, dass sie nichts Gutes im Schilde führen -- ich brauche nur einen Beweis, damit wir nicht unüberlegt handeln.\n\nHattet Ihr Glück?", completion = "Schon wieder Apotheker. Die kapieren es einfach nicht. Mal sehen, was dieses Mal los ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[26111] = { id = 26111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "… und er wird kommen", description = "Ich erfülle Euch nun mit den Energien des verderbenden Gesichtslosen.\n\nSchwimmt hinunter zu meinem Ködertotem im Graben im Nordosten. Nutzt das Totem, um die Energien zu entfesseln. Bringt mir das Gehirn ihres Anführers.\n\nRuft Ick'thys den Unergründlichen… und er wird kommen!", sourceObjective = "Besorgt Euch das Gehirn des Unergründlichen.", progress = "Habt Ihr es, {name}?\n\nMit dem Gehirn des Unergründlichen können wir vielleicht doch mit L'ghorek, dem sterbenden Ahnen vor uns, kommunizieren.", completion = "Und nun schauen wir mal, ob wir Euch in L'ghorek versetzen können, damit Ihr mit ihm sprecht, bevor er stirbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26112] = { id = 26112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällige Antworten", description = "Wie genau ist es den Kriegern der Dunkeleisenzwerge gelungen, bis hierher vor die Tore Eisenschmiedes zu kommen und beinahe unsere Stadt zu erobern?\n\nHerrscht nicht 'Kaiserin' Moira, Mitglied unseres hochgeschätzten Rates der Drei Hämmer, über die Dunkeleisenzwerge? Ohne ihr Wissen und ihre Zustimmung konnte das nicht geschehen. Das war keine zusammengewürfelte Gruppe rebellischer Zwerge, sondern eine gut ausgerüstete Invasionsstreitmacht.\n\nIch habe einen Bericht über die Schlacht um den Flugplatz zusammengestellt. Bringt ihn zum Hohen Sitz nach Eisenschmiede und konfrontiert sie damit!", sourceObjective = "Bringt Steinbrechers Bericht zu Moira Thaurissan im Hohen Sitz von Eisenschmiede.", progress = "Was hat diese Störung zu bedeuten?", completion = "Und was genau ist das?\n\n<Moira nimmt den Bericht entgegen. Sie wird blass, als sie ihn liest.>\n\nDas ist unmöglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[26113] = { id = 26113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae und Kinelory", description = "Die Horde besetzt Go'sheks Hof im Osten schon seit langem. Bei all unseren anderen Problemen hier fiel das nicht ins Gewicht. Aber nun gibt es Berichte über Untote in diesem Gebiet.\n\nAlles, was alarmierender ist als ein paar schlurfende Peons, gibt Anlass zu Nachforschungen. Das ist nicht das erste Mal, dass die Untoten auf dem Hof ihre dunklen Pläne vorantreiben. Ich habe meine besten Späher dorthin geschickt. Meldet Euch bei Quae und Kinelory. Sie werden Euch alles erzählen.", sourceObjective = "Findet Quae auf dem Hügel über Go'sheks Hof.", completion = "Die Zuflucht schickt Euch? Schön, dass es sie noch gibt.\n\nWir haben hier ein paar interessante Dinge beobachtet, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26114] = { id = 26114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae vertraut Euch", description = "<Quae sieht die Unterlagen durch.>\n\nAusdehnung...Gebietskontrolle... diese Untoten planen nichts neues, aber sie wollen ganz Arathi einnehmen. Wir müssen ihre Pläne stören.\n\nIch halte hier oben Wache. Ihr geht mit Kin und besorgt die Invasionspläne. Diese wandelnden Kadaver werden nicht einmal erfahren, welchen Tag wir haben.\n\nUnd passt auf sie auf, verstanden?", sourceObjective = "Sprecht mit Kinelory nahe Go'Sheks Hof im Arathihochland.", completion = "Die Seuche nahm uns unsere Freunde und Familien, aber die Verlassenen nahmen uns Phin. Sie sind nicht besser als die Geißel. Ich werde sie alle mit meinen eigenen Händen töten, wenn es sein muss.\n\nSagt Bescheid, wenn Ihr bereit seid. Wir können direkt anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26115] = { id = 26115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehen ist verstehen", description = "Bleibt bei mir, {name} und seht zu, wie unsere mächtige Waffe den Feind vernichtet!\n\nVersteht, was es bedeutet, zur Horde zu gehören!", sourceObjective = "Versteht, was es bedeutet, zur Horde zu gehören.", progress = "Habt Ihr es verstanden?", completion = "Jetzt endlich wisst Ihr, was es heißt, ein Mitglied der Horde zu sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26116] = { id = 26116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinelory schlägt zu", description = "Also gut, {name}. Wenn Ihr so weit seid... \n\nWollen wir?", sourceObjective = "Beschützt Kinelory, bis sie zu Quae zurückkehrt.", progress = "Bleibt besser bei Kinelory. Ich vertraue Euch, aber wenn ihr etwas zustoßen sollte, weiß ich nicht, was ich tun würde.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}. Danke.\n\nHoffentlich hat Euch Kin keine Probleme bereitet. Sie ist sehr zuvorkommend, aber tödlich für ihre Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26117] = { id = 26117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Süderstade", description = "Es gab Abende in der Taverne, nach denen Kinelory schlimmer aussah als jetzt. Ihr habt sie anscheinend gut beschützt.\n\nDie Zuflucht sollte von unserem Erfolg erfahren. Ich bleibe mit Kin hier, damit sie sich ausruhen kann. Geht ohne uns los.", sourceObjective = "Kehrt zu Kommandantin Amaren in der Zuflucht zurück.", completion = "Ich bin wirklich beeindruckt, {class}. Bei all dem, was hier geschieht, ist dies ein kleiner Trost.\n\nIhr habt die Untoten bekämpft, die Horde zurückgeworfen und die Opfer von Süderstade geehrt. Im Namen des Königreichs von Stromgarde verleihe ich Euch eine offizielle Belobigung und diese Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26118] = { id = 26118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasst den Botschafter", description = "Der Verrat des Botschafters wird mich noch lange verfolgen. Ihr müsst ihn verhaften, bevor er noch weiteren Schaden anrichtet oder schlimmer noch, bevor er entkommt und mit der Planung des nächsten Angriffs beginnt. Eisenschmiede wird erst sicher sein, wenn Botschafter Schlackenhammer sich nicht mehr frei in der Stadt bewegt.\n\nNehmt diese Fesseln und geht zur Botschaft der Dunkeleisenzwerge. Sie befindet sich nördlich des Hohen Sitzes, am Rand der Großen Schmiede. Verhaftet Botschafter Schlackenhammer und kehrt mit ihm zurück.", sourceObjective = "Geht zur Botschaft der Dunkeleisenzwerge und verhaftet Botschafter Schlackenhammer mit Hilfe der stabilen Handfesseln.", progress = "Wir müssen den Botschafter aufhalten, bevor er noch mehr Schaden anrichtet.", completion = "Der Botschafter wird uns keinen Ärger mehr machen. Er ist nicht der einzige Dunkeleisenzwerg, dessen Herz immer noch für den Schattenhammer schlägt. Das dürfen wir nie vergessen. Wir müssen wachsam sein und ihre Pläne vereiteln, sonst wird mein Sohn nur Ruinen und Asche erben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26119] = { id = 26119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Claim Our Stake Launched" }
quests[26120] = { id = 26120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahnsinnige Orc des Drachenmals", description = "Die Orcs des Drachenmals werden immer mehr zur Plage. Ihre waghalsigen Angriffe auf den Hain sind zwar lästig, verhelfen meinen Wachen aber wenigstens zu einigen nützlichen Übungseinheiten.\n\nMeine Späher haben jedoch beobachtet, dass sie schwarze Großdrachenwelpen mit Netzen einfangen. Das Letzte, was dieses Land gebrauchen kann, ist ein primitives Wiederaufleben der Drachenzähmung. Macht Euch auf den Weg nach Osten, {class}, und tötet die Welpendiebe. Sorgt dafür, dass ihre Dummheit uns nicht teuer zu stehen kommt.", sourceObjective = "Tötet 12 Welpendiebe des Drachenmals.", completion = "Die Orcs haben verstanden, dass sie nicht weiter nach Westen vordringen dürfen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26121] = { id = 26121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Ihr seht Spione da oben? Das ist nix gut… gar nix gut, <Genosse/Genossin>.\n\nKehrt zurück zu Korthuns Ende und vernichtet sie, mein Freund.", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[26122] = { id = 26122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umweltbewusstsein", description = "Habt Ihr je Unterseeboottreibstoff gerochen, {name}? Widerliches Zeug. Leider müssen wir große Mengen davon verbrennen, um die Verne anzutreiben. Und es riecht nicht nur abstoßend, sondern ist auch tödlich für die Tiere hier. Wir müssen bewusster mit unserer Umwelt umgehen.\n\nDie Meereswesen hier in der Gegend haben besonders öliges Fleisch. Bringt dieses Gerät zum Meeresdickicht direkt über dieser Höhle und benutzt es an den Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Ihr Öl kann vielleicht das Leben Hunderter anderer Meereslebewesen retten.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Bitte… Sagt den anderen Goblins nicht, dass ich Umweltschützer bin! Ich könnte ihren Spott nicht ertragen!", completion = "<Fiasco steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26123] = { id = 26123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwasserwölfe", description = "Willkommen, Freund!\n\nUnsere Verstärkung ist eingetroffen und bringt uns Nahrung, Orcs und neue Reittiere. Moment mal… Reittiere?!\n\nWie sollen wir uns denn unter Wasser auf einem WOLF fortbewegen?!\n\n<Kapitän Verne seufzt.>\n\nDirekt über dieser Höhle, im Meeresdickicht, findet Ihr hohe Säulen mit rotem, blättrigem Tang obenauf. In diesem Tang verstecken sich Seepferdchen besonders gerne. Werft dieses Lasso in den Tang und fangt uns ein paar NÜTZLICHE Reittiere.", sourceObjective = "Benutzt das Seepferdchenlasso in der Nähe des Tangs auf den Säulen im Meeresdickicht, um 5 panische Seepferdchen zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26124] = { id = 26124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Die Allianz hat Spione in dieser Gegend? Die Schattenhöhle ist ganz in der Nähe und das neue Unterseeboot der Horde, die Verne, befindet sich dort! Die Allianz darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Höhle darüber informieren… nachdem Ihr mehr von diesen hinterhältigen Spionen der Allianz den Garaus gemacht habt!", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Allianz auf der Hut sein. Die Verne hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26125] = { id = 26125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Ihr habt da oben Spione gesehen? Das ist nicht gut… Das lasse ich nicht zu!\n\nKehrt zum Meeresdickicht zurück und werdet sie los, bevor sie sich in unser Versteck einschleichen können.", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26126] = { id = 26126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Treibstoff", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Schattenhöhle, um den perfekten Biotreibstoff herzustellen.", progress = "Wir haben noch nicht die richtige Kombination gefunden, {name}. Macht weiter! Ich bin mir sicher, dass Ihr es schafft.", completion = "Das war's. Ab heute werde ich die Verne mit Biotreibstoff betreiben. Ich werde ein paar Männer nach oben schicken, um mehr Öl zu besorgen.\n\nDenkt nur an die ganzen Meerestiere, die wir heute gerettet haben, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26127] = { id = 26127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Enthüllung des Schattenhammers", description = "Ich dachte ebenso wie alle anderen, dass es sich bei diesen Narren nur um nichtsnutzige Dunkeleisenzwerge handelte, aber diese Wahnsinnigen sind überzeugte Kultisten!\n\nDer Schattenhammer will nichts anderes als die Zerstörung der ganzen Welt. Sie haben sich Todesschwinge und Ragnaros angeschlossen und sind eng mit den Dunkeleisenzwergen verbunden.\n\nAber es ist egal, wer sie sind, wichtig ist nur, dass sie sich in Dun Modr aufhalten und entfernt werden müssen! Ich werde keinen von ihnen durchlassen. Geht zu ihnen und zertrümmert ein paar Schädel!", sourceObjective = "Tötet 12 Mitglieder des Schattenhammers in Dun Modr.", completion = "Gute Leistung, Junge, aber wir haben keine Zeit für Feste. Der Thandolübergang wird bedroht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26128] = { id = 26128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Thandolübergang", description = "Ich habe den Thandolübergang schon einmal vor der Zerstörung bewahrt. Damals kämpfte ich gegen die Dunkeleisenzwerge. Das gleiche tat mein Vater und dessen Vater vor ihm...\n\nDie einzigen Dunkeleisenzwerge, die mir entkamen, liefen direkt auf die Brücke zu. Etwas stimmt nicht. Ich befürchte, dass wir bei unserer Ankunft in eine üble Falle stürmen werden.\n\nIch könnte Eure Hilfe brauchen, {name}. Für Eisenschmiede. Seid Ihr dabei?", sourceObjective = "Besiegt Calamoth Aschbart am Thandolübergang.", sourceObjectiveStatus = "unverified-source-field" }
quests[26129] = { id = 26129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenbrüder", description = "Hört zu, {name}. Zum ersten Mal seit dem Bürgerkrieg bin ich mit Graumähne einer Meinung. Es ist an der Zeit, unsere Fehde endlich beizulegen.\n\nDiesen Bestien scheint es egal zu sein, ob man Rebell oder Königstreuer ist.\n\nÜberbringt Graumähne meine Antwort. Meine Männer werden sich seinen Leuten anschließen.\n\nNicht weit von hier gibt es ein sicheres Versteck, in Josiahs Keller. Meine Jungs haben dort ein wenig schwere Artillerie gelagert.\n\nSagt dem König, dass er sich jederzeit in unserer Waffenkammer bedienen kann.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel in Gilneas.", completion = "Eine Waffenkammer der Rebellen? In meiner eigenen Stadt?\n\nWas zur Hölle führte Crowley nur im Schilde?", sourceObjectiveStatus = "unverified-source-field" }
quests[26130] = { id = 26130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Verbindung zu L'ghorek", description = "L'ghorek ist der Ahn, der auf der Klippe gegenüber von uns ruht. Er wird kontrolliert. Etwas Riesiges unter uns verschlingt seine Lebensenergien.\n\nUnter L'ghorek gibt es eine Höhle, die als Muscheltiefe bekannt ist. In dieser Höhle befinden sich drei mächtige Ogermagier, die ein Ritual abhalten, das das Ding aus der Tiefe mit dem Ahnen verbindet. Ihr müsst die drei töten, um die Verbindung zu L'ghorek zu unterbrechen.", sourceObjective = "Tötet Ur'Goz, Sku'Bu und Neph'Lahim.", completion = "Jetzt, da L'ghoreks Verbindung unterbrochen wurde, müssen wir versuchen, mit ihm Kontakt aufzunehmen. Ich kann spüren, dass der Ahn noch lebt, aber er ist sehr schwach.", sourceObjectiveStatus = "unverified-source-field" }
quests[26131] = { id = 26131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Loch Modan", description = "Seit Stunden warte ich darauf, dass sich der Rat meine Bitte anhört, aber es sieht nicht gut aus. Moira scheint darauf versessen zu sein, den Rat lahmzulegen.\n\nWährenddessen leidet Loch Modan. Wir haben viele Feinde, aber nur wenige Ressourcen. Würdet Ihr mich vielleicht anhören, {name}, wenn der Rat nicht dazu gewillt ist? Sprecht mit Gryth Thurden, dem Greifenmeister von Eisenschmiede. Er hält sich im östlichen Teil der Großen Schmiede auf. Er wird Euch kostenlos zum Südtorpass fliegen lassen. Stellt Euch nach Eurer Ankunft Pilot Hammerfuß vor.", sourceObjective = "Bittet Gryth Thurden in der Großen Schmiede um einen Flug nach Loch Modan. Sprecht bei Eurer Ankunft mit Pilot Hammerfuß.", completion = "Ihr könnt Euch nicht vorstellen, wie froh ich bin, neue Gesichter aus Eisenschmiede zu sehen. Vielleicht war es doch keine Verschwendung, Gebirgsjäger Gerstenbräu dorthin zu entsenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26132] = { id = 26132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nWir können nicht riskieren, dass sie diese Entartungen später gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, zerstört so viele von den Dingern, wie Ihr könnt.", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Das Letzte, was wir brauchen, ist ein Haufen beschworener Kreaturen, die während unseres letzten Angriffs unsere Streitmächte anfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26133] = { id = 26133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nIch will nicht miterleben, dass sie diese Entartungen gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, vernichtet sie alle!", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Eine Sache weniger, um die wir uns bei unserem letzten Angriff sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26134] = { id = 26134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts mehr für Euch hier", description = "Es gibt hier nichts mehr für Euch, {name}. Was mich betrifft, ich muss nur noch Mashas Leiche begraben. Wenn ich das getan habe, werde ich zur Bombenabwurfstelle gehen und das Nachwachsen einleiten. Vielleicht wird eines Tages ein neuer Hain erblühen - ein Hain erfüllt mit dem Geist meines Kindes und denen der gefallenen jungen Nachtelfen.\n\nIch habe von einem Blutelf namens Furien in Desolace gehört, der nach gleichgesinnten Abenteurern sucht. Vielleicht solltet Ihr ihn aufsuchen.\n\nLebt wohl, <Freund/Freundin>, ich werde Euch nie vergessen.", sourceObjective = "Sprecht mit Furien in Tethris Aran in Desolace.", completion = "<Furien stöhnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26135] = { id = 26135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", sourceObjective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", completion = "Diener des Alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n{name}, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
